// StayTW Study — TOCFL Level 2 文法
// 正本: 國家教育研究院「臺灣華語文能力基準(TBCL)」語法點表 496 点。
//   第2級 の点をそのまま並べ、最後に官方の表に無い点(書面語・進階)を足している。
//   語法點名(t)と1つ目の例文は官方のまま。説明と訳と2つ目の例文はこちらで書いた。
//   作り直し: node scripts/gen-grammar.mjs → node scripts/build-grammar.mjs
// 形式: id, cat, t=語法點名, g=一言の意味, p=文型, ex=解説, eg=例文[{z,py,j,e,k}]
const GRAMMAR_L2 = [
{"id":"g2-016","cat":"基本文型","t":"Vs（的）N","g":{"j":"形容詞(狀態動詞)＋的＋名詞で名詞を修飾する","e":"Modifying a noun with a stative verb + 的","k":"상태동사+的+명사로 명사를 수식함"},"p":{"j":"Vs（很）＋的＋N","e":"Vs (+ 很) + 的 + N","k":"Vs(+很)+的+N"},"ex":{"j":"Vs(狀態動詞)で名詞を修飾する時は「的」を挟むのが基本形。「很好看的電影」のように「很＋Vs＋的＋N」で使う。「很好看電影」のように的を落とす誤りに注意する。","e":"Vs (stative verbs) modify a noun with 的 in between, as in 'hěn hǎokàn de diànyǐng'. A common mistake is dropping 的 before the noun ('hěn hǎokàn diànyǐng'), which is ungrammatical.","k":"Vs(상태동사)로 명사를 수식할 때는 的를 넣는 것이 기본형이다. '很好看的電影'처럼 '很+Vs+的+N' 형태로 쓴다. 的를 빼고 명사를 바로 붙이는 실수에 주의해야 한다."},"eg":[{"z":"這是一部很<em>好看的</em>電影。","py":"Zhè shì yí bù hěn hǎokàn de diànyǐng.","j":"これはとても面白い(見応えのある)映画です。","e":"This is a very good movie.","k":"이것은 아주 재미있는 영화입니다."},{"z":"他是一個很<em>聰明的</em>學生。","py":"Tā shì yí ge hěn cōngmíng de xuéshēng.","j":"彼はとても賢い学生です。","e":"He is a very smart student.","k":"그는 아주 똑똑한 학생입니다."}]},
{"id":"g2-017","cat":"アスペクト","t":"V了1","g":{"j":"動作がすでに完了したことを表す","e":"Marks that an action has been completed","k":"동작이 이미 완료되었음을 나타냄"},"p":{"j":"S＋V＋了＋(數量)＋O","e":"S + V + 了 + (Quantity) + O","k":"S+V+了+(수량)+O"},"ex":{"j":"了1は動詞の直後につけて動作の完了を表す。過去の時間詞(昨天など)とよく一緒に使われる。否定は「不V了」ではなく「沒(有)V」を使う点に注意する。","e":"了1 attaches right after the verb to mark that the action is completed, often with a past time word like 昨天. Note the negative form uses 沒(有) + V, not 不V了.","k":"了1은 동사 바로 뒤에 붙어 동작이 완료되었음을 나타내며 昨天처럼 과거 시간어와 자주 쓰인다. 부정은 不가 아니라 沒(有)+동사를 쓴다는 점에 주의해야 한다."},"eg":[{"z":"我昨天<em>買了</em>很多書。","py":"Wǒ zuótiān mǎi le hěn duō shū.","j":"私は昨日たくさんの本を買いました。","e":"I bought a lot of books yesterday.","k":"나는 어제 책을 많이 샀어요."},{"z":"他昨天晚上<em>吃了</em>三碗飯。","py":"Tā zuótiān wǎnshang chī le sān wǎn fàn.","j":"彼は昨日の夜、ご飯を三杯食べました。","e":"He ate three bowls of rice last night.","k":"그는 어제 저녁에 밥을 세 그릇 먹었어요."}]},
{"id":"g2-018","cat":"接続","t":"和1","g":{"j":"名詞と名詞をつなぐ「〜と」","e":"Connects two nouns, meaning 'and'","k":"명사와 명사를 연결하는 '~와/과'"},"p":{"j":"N1＋和＋N2","e":"N1 + 和 + N2","k":"N1+和+N2"},"ex":{"j":"和1は名詞と名詞(または名詞句)を並べて「〜と」の意味を表す純粋な接続詞。動詞句や文と文はつなげない(その場合は「然後」などを使う)。","e":"和1 is a conjunction that links two nouns or noun phrases, meaning 'and'. It cannot connect two verb phrases or clauses — use words like 然後 for that instead.","k":"和1은 명사(구)와 명사(구)를 연결하는 순수 접속사로 '~와/과'의 뜻이다. 동사구나 문장끼리는 연결할 수 없으며 그 경우 然後 등을 쓴다."},"eg":[{"z":"這間餐廳的點心很棒，大人<em>和</em>小孩都喜歡。","py":"Zhè jiān cāntīng de diǎnxīn hěn bàng, dàrén hàn xiǎohái dōu xǐhuān.","j":"このレストランの点心はとても美味しくて、大人も子供もみんな好きです。","e":"The snacks at this restaurant are great — both adults and children like them.","k":"이 식당의 딤섬은 정말 맛있어서 어른과 아이 모두 좋아해요."},{"z":"我<em>和</em>姊姊一起去看電影。","py":"Wǒ hàn jiějie yìqǐ qù kàn diànyǐng.","j":"私は姉と一緒に映画を見に行きます。","e":"I'm going to watch a movie with my older sister.","k":"나는 언니와 같이 영화를 보러 가요."}]},
{"id":"g2-019","cat":"否定","t":"沒（有）1","g":{"j":"存在や所有がないことを表す「〜がない」","e":"Negates existence or possession: 'there is no...'","k":"존재나 소유가 없음을 나타냄 '~이 없다'"},"p":{"j":"(S)＋沒(有)＋O","e":"(S) + 沒(有) + O","k":"(S)+沒(有)+O"},"ex":{"j":"「有」の否定は「不有」ではなく必ず「沒(有)」を使う。有は省略して「沒」だけでもよい。存在文(〜に…がある/ない)にも所有文(〜を持っている/いない)にも使える。","e":"The negation of 有 is always 沒(有), never 不有 — 有 can be dropped, leaving just 沒. It covers both existence ('there is no park') and possession ('I have no money').","k":"有의 부정은 반드시 沒(有)를 쓰며 不有라고 하지 않는다. 有는 생략해서 沒만 써도 된다. 존재문과 소유문 모두에 쓸 수 있다."},"eg":[{"z":"圖書館附近<em>沒有</em>公園。","py":"Túshūguǎn fùjìn méiyǒu gōngyuán.","j":"図書館の近くには公園がありません。","e":"There is no park near the library.","k":"도서관 근처에는 공원이 없어요."},{"z":"我的皮包裡<em>沒有</em>錢。","py":"Wǒ de píbāo lǐ méiyǒu qián.","j":"私の財布の中にはお金がありません。","e":"There's no money in my wallet.","k":"내 지갑 안에는 돈이 없어요."}]},
{"id":"g2-020","cat":"助動詞","t":"會1","g":{"j":"未来の推測・可能性を表す「〜するだろう」","e":"Expresses a future possibility or prediction","k":"미래의 가능성이나 추측을 나타냄"},"p":{"j":"S＋會＋VP","e":"S + 會 + VP","k":"S+會+VP"},"ex":{"j":"會1は未来の出来事に対する推測・可能性を表し、「明天」「今年」などの時間詞や「可能」と一緒に使われやすい。学んで身につけた技能を表す「會(泳げる等)」とは別の用法なので混同しないこと。","e":"會1 expresses a prediction or possibility about the future, often paired with time words like 明天/今年 or 可能. Don't confuse it with the other 會 that means a learned ability (e.g. 我會游泳).","k":"會1은 미래에 대한 추측이나 가능성을 나타내며 明天/今年 같은 시간어나 可能와 함께 자주 쓰인다. 배워서 습득한 능력을 뜻하는 또 다른 會(예: 我會游泳)와 혼동하지 않아야 한다."},"eg":[{"z":"你今年<em>會</em>出國嗎？","py":"Nǐ jīnnián huì chūguó ma?","j":"あなたは今年海外に行きますか。","e":"Will you go abroad this year?","k":"당신은 올해 해외에 나갈 건가요?"},{"z":"明天可能<em>會</em>下雨。","py":"Míngtiān kěnéng huì xiàyǔ.","j":"明日は雨が降るかもしれません。","e":"It might rain tomorrow.","k":"내일 비가 올 수도 있어요."}]},
{"id":"g2-021","cat":"アスペクト","t":"V著1","g":{"j":"動作・状態の持続","e":"Continuing action or state","k":"동작·상태의 지속"},"p":{"j":"V ＋ 著 (＋ 目的語)","e":"V + 著 (+ Object)","k":"V ＋ 著 (＋ 목적어)"},"ex":{"j":"「V著」は動作や状態がそのまま続いていることを表す。「了」(完了)や「在」(進行中の動作)と違い、結果としての状態継続に使う。「戴著帽子」は「かぶっている状態」を表す。過去形と混同しないよう注意。","e":"\"V著\" expresses a state or action that continues/persists, unlike \"了\" (completion) or \"在\" (an action in progress). \"戴著帽子\" describes the ongoing state of wearing a hat. Don't mistake 著 for a past-tense marker.","k":"\"V著\"는 동작이나 상태가 그대로 계속됨을 나타낸다. 완료를 뜻하는 \"了\", 진행 중인 동작을 뜻하는 \"在\"와는 다르며 결과 상태의 지속을 나타낸다. \"戴著帽子\"는 \"쓰고 있는 상태\"를 뜻한다. 과거형으로 착각하지 않도록 주의."},"eg":[{"z":"他<em>戴著</em>帽子。","py":"Tā dàizhe màozi.","j":"彼は帽子をかぶっている。","e":"He is wearing a hat.","k":"그는 모자를 쓰고 있다."},{"z":"她<em>穿著</em>紅色的衣服。","py":"Tā chuānzhe hóngsè de yīfu.","j":"彼女は赤い服を着ている。","e":"She is wearing red clothes.","k":"그녀는 빨간 옷을 입고 있다."}]},
{"id":"g2-022","cat":"数量","t":"序數","g":{"j":"序数(第〜)","e":"Ordinal numbers (the ~th)","k":"서수(제~)"},"p":{"j":"第 ＋ 數字 ＋ (量詞/名詞)","e":"第 + Number + (Measure word/Noun)","k":"第 ＋ 숫자 ＋ (양사/명사)"},"ex":{"j":"「第」をつけて順番を表す。数量を数える基数(一個、兩次など)と違い、順序を示す時は必ず「第」が必要。「第一」「第二」のように量詞や動詞の前に置く。「第」を落とさないよう注意。","e":"Add \"第\" before a number to show sequence/order, unlike cardinal numbers used for counting quantity (一個, 兩次). \"第一\" = \"first,\" \"第二\" = \"second.\" Don't drop \"第\" when expressing order.","k":"\"第\"를 숫자 앞에 붙여 순서를 나타낸다. 수량을 세는 기수(一個, 兩次 등)와 달리 순서를 나타낼 때는 반드시 \"第\"가 필요하다. \"第一\", \"第二\"처럼 양사나 동사 앞에 쓴다. \"第\"를 빠뜨리지 않도록 주의."},"eg":[{"z":"這是我<em>第一次</em>來臺灣。","py":"Zhè shì wǒ dì-yī cì lái Táiwān.","j":"私が臺灣に来るのはこれが初めてです。","e":"This is my first time coming to Taiwan.","k":"저는 이번에 처음으로 대만에 왔습니다."},{"z":"這是我<em>第二次</em>坐捷運。","py":"Zhè shì wǒ dì-èr cì zuò jiéyùn.","j":"私が捷運に乗るのはこれが二回目です。","e":"This is my second time taking the MRT.","k":"저는 이번이 두 번째로 지하철(MRT)을 타는 것입니다."}]},
{"id":"g2-023","cat":"接続","t":"如果","g":{"j":"もし〜なら(仮定)","e":"If... (conditional)","k":"만약 ~라면(가정)"},"p":{"j":"如果 ＋ 條件句，(就) ＋ 結果句","e":"如果 + condition, (就) + result","k":"如果 ＋ 조건절, (就) ＋ 결과절"},"ex":{"j":"「如果」は仮定条件を表し、後半の文に「就」を伴うことが多い。「要是」も似た意味だが「如果」の方がやや書きことば寄り。「如果」を省いて「就」だけにしないよう注意。","e":"\"如果\" introduces a hypothetical condition, and the result clause often pairs with \"就.\" It is similar to \"要是\" but slightly more formal/written. A common mistake is dropping \"如果\" and keeping only \"就.\"","k":"\"如果\"는 가정 조건을 나타내며 뒤 절에 \"就\"가 자주 함께 쓰인다. \"要是\"와 뜻이 비슷하지만 \"如果\"가 약간 더 문어체에 가깝다. \"就\"만 남기고 \"如果\"를 빠뜨리지 않도록 주의."},"eg":[{"z":"<em>如果</em>下雨，我就不出門。","py":"Rúguǒ xiàyǔ, wǒ jiù bù chūmén.","j":"もし雨が降ったら、私は外出しません。","e":"If it rains, I won't go out.","k":"만약 비가 오면 저는 나가지 않을 거예요."},{"z":"<em>如果</em>你有空，我們一起去看電影。","py":"Rúguǒ nǐ yǒu kòng, wǒmen yìqǐ qù kàn diànyǐng.","j":"もし時間があれば、一緒に映画を見に行きましょう。","e":"If you're free, let's go watch a movie together.","k":"만약 시간이 있으면 우리 같이 영화 보러 가요."}]},
{"id":"g2-024","cat":"助動詞","t":"可以1","g":{"j":"許可(〜してもよい)","e":"Permission (may/can)","k":"허가(~해도 된다)"},"p":{"j":"(不) ＋ 可以 ＋ V","e":"(不) + 可以 + V","k":"(不) ＋ 可以 ＋ V"},"ex":{"j":"「可以」は許可を表す助動詞。「不可以」で禁止を表す。能力を表す「會」や条件的可能を表す「能」と混同しないよう注意。「可以」は主に許可・許容の意味を持つ。","e":"\"可以\" is an auxiliary verb expressing permission; \"不可以\" expresses prohibition. Don't confuse it with \"會\" (learned ability) or \"能\" (capability/condition) — \"可以\" mainly conveys permission or what is allowed.","k":"\"可以\"는 허가를 나타내는 조동사이며 \"不可以\"는 금지를 나타낸다. 능력을 뜻하는 \"會\"나 조건적 가능을 뜻하는 \"能\"과 혼동하지 않도록 주의. \"可以\"는 주로 허가·허용의 의미다."},"eg":[{"z":"上課不<em>可以</em>吃東西。","py":"Shàngkè bù kěyǐ chī dōngxi.","j":"授業中は物を食べてはいけません。","e":"You may not eat during class.","k":"수업 중에는 음식을 먹으면 안 됩니다."},{"z":"這裡<em>可以</em>拍照嗎？","py":"Zhèlǐ kěyǐ pāizhào ma?","j":"ここで写真を撮ってもいいですか。","e":"Can I take photos here?","k":"여기서 사진을 찍어도 되나요?"}]},
{"id":"g2-025","cat":"助動詞","t":"要2","g":{"j":"〜しなければならない(必要・義務)","e":"Must/need to (necessity)","k":"~해야 한다(필요·의무)"},"p":{"j":"主語 ＋ 要 ＋ V","e":"Subject + 要 + V","k":"주어 ＋ 要 ＋ V"},"ex":{"j":"この「要」は義務・必要性を表す用法で、「〜したい」という願望を表す「要1」とは意味が異なる。文脈で判断する必要があり、「要記得」(忘れずに〜する)のように忠告・念押しの場面でよく使われる。","e":"This \"要\" expresses necessity or obligation (\"must/need to\"), distinct from \"要1\" meaning \"want to.\" Context determines the reading — it's common in advice or reminders, e.g. \"要記得\" (must remember to).","k":"이 \"要\"는 의무·필요성을 나타내는 용법으로 \"~하고 싶다\"는 뜻의 \"要1\"과는 다르다. 문맥에 따라 뜻을 판단해야 하며, \"要記得\"(잊지 말고 ~하다)처럼 충고나 당부의 상황에서 자주 쓰인다."},"eg":[{"z":"你<em>要</em>記得打電話給王老師。","py":"Nǐ yào jìde dǎ diànhuà gěi Wáng lǎoshī.","j":"あなたは王先生に電話するのを忘れずに覚えておかなければなりません。","e":"You must remember to call Teacher Wang.","k":"당신은 왕 선생님께 전화하는 것을 꼭 기억해야 합니다."},{"z":"你<em>要</em>小心過馬路。","py":"Nǐ yào xiǎoxīn guò mǎlù.","j":"道を渡る時は気をつけなければなりません。","e":"You need to be careful crossing the street.","k":"길을 건널 때는 조심해야 합니다."}]},
{"id":"g2-026","cat":"助動詞","t":"要3","g":{"j":"~するつもりだ(意向・誘い)","e":"be going to / plan to (intention)","k":"~할 생각이다(의향)"},"p":{"j":"主語＋要＋動詞(句)＋(嗎)？","e":"Subject + yào + VP (+ ma)?","k":"주어 + 要 + 동사(구) + (嗎)?"},"ex":{"j":"要＋動詞は「~するつもり」という意向や誘いを表す。要1(必要)や要2(欲しい＋名詞)と違い、要3は後ろに動詞句が来る。「要不要」で誘う言い方もよく使う。","e":"Yào + verb expresses intention or an invitation to do something. Unlike yào1 (need) or yào2 (want + noun), yào3 is followed by a verb phrase, and 'yào bu yào' is a common way to invite someone.","k":"要+동사는 '~할 것이다/~하려 하다'라는 의향이나 권유를 나타낸다. 要1(필요)이나 要2(원하다+명사)와 달리 뒤에 동사구가 온다. '要不要'로 권유할 때도 자주 쓴다."},"eg":[{"z":"你今天<em>要</em>一起吃飯嗎？","py":"Nǐ jīntiān yào yìqǐ chīfàn ma?","j":"今日、一緒にご飯を食べませんか？","e":"Are you going to eat together today?","k":"오늘 같이 밥 먹을래요?"},{"z":"明天你<em>要</em>跟我去逛夜市嗎？","py":"Míngtiān nǐ yào gēn wǒ qù guàng yèshì ma?","j":"明日、私と夜市に行きませんか？","e":"Are you going to go to the night market with me tomorrow?","k":"내일 저랑 야시장에 갈래요?"}]},
{"id":"g2-027","cat":"補語","t":"時量補語","g":{"j":"動作の継続時間を表す補語","e":"duration complement (how long an action lasts)","k":"동작의 지속 시간을 나타내는 보어"},"p":{"j":"動詞＋(目的語)＋時間の長さ＋(了)","e":"Verb (+ Object) + duration + (le)","k":"동사(+목적어)+시간량+(了)"},"ex":{"j":"動詞の後に時間の長さを置いて動作の継続時間を表す。時点(時候)は動詞の前、時量(期間)は動詞の後に置く点に注意。目的語がある場合は動詞を繰り返すか目的語を省くことが多い。","e":"Place a duration of time after the verb to show how long an action lasts. A point in time goes before the verb, but a duration goes after it — a common mix-up. When there's an object, the verb is often repeated or the object is dropped.","k":"동사 뒤에 시간의 길이를 두어 동작이 지속된 시간을 나타낸다. 시점은 동사 앞, 시량(기간)은 동사 뒤에 오는 점에 주의. 목적어가 있으면 동사를 반복하거나 목적어를 생략하는 경우가 많다."},"eg":[{"z":"他已經來臺灣<em>一個月</em>了。","py":"Tā yǐjīng lái Táiwān yí ge yuè le.","j":"彼はもう台湾に来て1か月になります。","e":"He has already been in Taiwan for one month.","k":"그는 벌써 대만에 온 지 한 달이 되었어요."},{"z":"我在台北住了<em>三年</em>。","py":"Wǒ zài Táiběi zhùle sān nián.","j":"私は台北に3年住んでいます。","e":"I have lived in Taipei for three years.","k":"저는 타이베이에서 3년 살았어요."}]},
{"id":"g2-028","cat":"接続","t":"但是","g":{"j":"しかし・でも(逆接)","e":"but / however (contrast)","k":"그러나・하지만(역접)"},"p":{"j":"A，但是＋B","e":"A, dànshì + B","k":"A, 但是 + B"},"ex":{"j":"前後で対立・逆接の関係を示す。前の文に「雖然」がなくても但是だけで使える。可是と意味は近いが、但是のほうがやや書き言葉寄り。","e":"Dànshì links two clauses in contrast; the first clause doesn't need 雖然 for dànshì to work on its own. It's close in meaning to kěshì, but dànshì sounds slightly more formal/written.","k":"앞뒤 절이 대립・역접 관계임을 나타낸다. 앞 절에 雖然이 없어도 但是만으로 쓸 수 있다. 可是와 의미가 비슷하지만 但是가 조금 더 문어체에 가깝다."},"eg":[{"z":"這個箱子很大，<em>但是</em>裡面的東西很輕。","py":"Zhège xiāngzi hěn dà, dànshì lǐmiàn de dōngxi hěn qīng.","j":"この箱は大きいですが、中の物は軽いです。","e":"This box is big, but the things inside are light.","k":"이 상자는 크지만, 안에 있는 물건은 가벼워요."},{"z":"我很想去，<em>但是</em>我沒有時間。","py":"Wǒ hěn xiǎng qù, dànshì wǒ méiyǒu shíjiān.","j":"私はとても行きたいですが、時間がありません。","e":"I really want to go, but I don't have time.","k":"저는 정말 가고 싶지만, 시간이 없어요."}]},
{"id":"g2-029","cat":"助動詞","t":"能1","g":{"j":"~できる(容量・条件)","e":"can (capacity/condition)","k":"~할 수 있다(용량・조건)"},"p":{"j":"主語＋能＋動詞(句)","e":"Subject + néng + VP","k":"주어 + 能 + 동사(구)"},"ex":{"j":"能は容量や条件によって「~できる」ことを表す。学んで身につけた技能を言う「會」や許可を表す「可以」と混同しやすいが、能1は物理的な条件・容量に重点がある。","e":"Néng expresses being able to do something because of conditions or capacity. It's easy to confuse with huì (a learned skill) or kěyǐ (permission), but néng1 focuses on physical/objective conditions.","k":"能은 조건이나 용량에 따른 '~할 수 있다'를 나타낸다. 배워서 익힌 능력을 말하는 會나 허가를 뜻하는 可以와 헷갈리기 쉽지만, 能1은 물리적・객관적 조건에 초점이 있다."},"eg":[{"z":"他的車<em>能</em>坐七個人。","py":"Tā de chē néng zuò qī ge rén.","j":"彼の車は7人乗ることができます。","e":"His car can seat seven people.","k":"그의 차는 일곱 명이 탈 수 있어요."},{"z":"這台電梯<em>能</em>坐十個人。","py":"Zhè tái diàntī néng zuò shí ge rén.","j":"このエレベーターは10人乗ることができます。","e":"This elevator can hold ten people.","k":"이 엘리베이터는 열 명이 탈 수 있어요."}]},
{"id":"g2-030","cat":"アスペクト","t":"V過1","g":{"j":"~したことがある(経験)","e":"have done ... before (experience)","k":"~한 적이 있다(경험)"},"p":{"j":"動詞＋過＋(目的語)","e":"V + guò (+ Object)","k":"동사+過(+목적어)"},"ex":{"j":"過は「~した経験がある」ことを表すアスペクト助詞で、動詞の直後につける。完了を表す「了」と違い、過去に経験したかどうかに焦点がある。否定は「沒(有)＋V過」。","e":"Guò marks past experience ('have done X before') and attaches right after the verb. Unlike le (completion), guò focuses on whether the experience ever happened; negate with méi(yǒu) + V + guò.","k":"過는 '~한 적이 있다'는 경험을 나타내는 상(aspect) 조사로 동사 바로 뒤에 붙는다. 완료를 나타내는 了와 달리 경험의 유무에 초점이 있으며, 부정은 '沒(有)+동사+過'로 한다."},"eg":[{"z":"我看<em>過</em>這部電影。","py":"Wǒ kànguo zhè bù diànyǐng.","j":"私はこの映画を見たことがあります。","e":"I have watched this movie before.","k":"저는 이 영화를 본 적이 있어요."},{"z":"我吃<em>過</em>臭豆腐。","py":"Wǒ chīguo chòudòufu.","j":"私は臭豆腐を食べたことがあります。","e":"I have eaten stinky tofu before.","k":"저는 취두부를 먹어 본 적이 있어요."}]},
{"id":"g2-031","cat":"接続","t":"就1","g":{"j":"〜したらすぐ","e":"as soon as / then","k":"~하면 바로"},"p":{"j":"A + 就 + B","e":"A + jiù + B","k":"A + 就 + B"},"ex":{"j":"「就」は前の動作の直後に次の動作が間を置かず続くことを表す。「才」(遅れてやっと)との違いに注意。「A就B」の形でAの直後にBが起こる。","e":"\"就\" links two events, showing B happens right after A with no delay — like \"as soon as.\" Contrast with \"才,\" which implies lateness or difficulty.","k":"'就'는 A가 일어나자마자 바로 B가 일어남을 나타낸다. '才'(늦게, 어렵게)와 헷갈리지 않도록 주의. 'A就B' 형태로 쓰인다."},"eg":[{"z":"你回到家<em>就</em>給我打電話。","py":"Nǐ huídào jiā jiù gěi wǒ dǎ diànhuà.","j":"家に着いたらすぐ電話してね。","e":"Call me as soon as you get home.","k":"집에 도착하면 바로 나한테 전화해."},{"z":"你吃完飯<em>就</em>去洗澡。","py":"Nǐ chīwán fàn jiù qù xǐzǎo.","j":"ご飯を食べ終わったらすぐお風呂に入って。","e":"Go take a shower as soon as you finish eating.","k":"밥 다 먹으면 바로 씻어."}]},
{"id":"g2-032","cat":"特殊構文","t":"「的」後接成分省略","g":{"j":"〜なもの(名詞省略)","e":"the ~ one (noun omitted)","k":"~것 (명사 생략)"},"p":{"j":"形容詞 + 的","e":"Adj + de","k":"형용사 + 的"},"ex":{"j":"話の流れで名詞が分かる場合、「的」の後の名詞を省略できる。「藍的」は「藍色的外套」の省略形で、前に出た名詞にしか使えない。","e":"When the noun after \"的\" is clear from context, it can be dropped — \"藍的\" stands in for \"藍色的外套.\" Only works when the referent was already mentioned.","k":"앞 문맥에서 명사가 이미 언급되었으면 '的' 뒤의 명사를 생략할 수 있다. '藍的'는 '藍色的外套'의 생략형이다."},"eg":[{"z":"我喜歡<em>藍的</em>。","py":"Wǒ xǐhuān lán de.","j":"私は青いのが好きです。","e":"I like the blue one.","k":"저는 파란 것이 좋아요."},{"z":"這件太貴了，我要<em>便宜的</em>。","py":"Zhè jiàn tài guì le, wǒ yào piányí de.","j":"これは高すぎるので、安いのが欲しいです。","e":"This one is too expensive, I want the cheap one.","k":"이건 너무 비싸서 저는 싼 것을 원해요."}]},
{"id":"g2-033","cat":"助動詞","t":"會2","g":{"j":"〜できる(習得した技能)","e":"can (learned skill)","k":"~할 수 있다 (배운 기능)"},"p":{"j":"會 + 不 + 會 + V?","e":"huì + bù + huì + V?","k":"會 + 不 + 會 + V?"},"ex":{"j":"ここでの「會」は経験や練習で身につけた能力を表す(運転できる、楽器が弾けるなど)。「能」(状況的に可能)や「可以」(許可)と混同しないよう注意。","e":"\"會\" here expresses a learned/acquired skill (like driving or playing an instrument). Don't confuse it with \"能\" (situational ability) or \"可以\" (permission).","k":"여기서 '會'는 배워서 익힌 능력(운전, 악기 등)을 나타낸다. 상황적 가능을 뜻하는 '能'이나 허가를 뜻하는 '可以'와 혼동하지 않도록 주의."},"eg":[{"z":"你<em>會不會</em>開車？","py":"Nǐ huì bú huì kāichē?","j":"あなたは車を運転できますか?","e":"Can you drive a car?","k":"너 운전할 수 있어?"},{"z":"我姊姊<em>會</em>彈鋼琴，我不<em>會</em>。","py":"Wǒ jiějie huì tán gāngqín, wǒ bú huì.","j":"姉はピアノが弾けますが、私は弾けません。","e":"My older sister can play the piano, but I can't.","k":"우리 언니는 피아노를 칠 줄 알지만, 저는 못 쳐요."}]},
{"id":"g2-034","cat":"助動詞","t":"能2","g":{"j":"〜できる(状況的可能)","e":"can (situational ability)","k":"~할 수 있다 (상황적 가능)"},"p":{"j":"不能 + V","e":"bù néng + V","k":"不能 + V"},"ex":{"j":"「能」は体調や状況によって「〜できる/できない」を表す。学んで身につけた能力を表す「會」とは違い、一時的な制限のニュアンスを持つ。","e":"\"能\" expresses ability/possibility due to physical condition or circumstances (e.g., being sick). Unlike \"會\" (learned skill), it often implies a temporary restriction.","k":"'能'은 건강 상태나 상황에 따른 가능/불가능을 나타낸다. 배운 능력을 뜻하는 '會'와 달리 일시적인 제약의 뉘앙스가 있다."},"eg":[{"z":"他感冒了，今天<em>不能</em>運動。","py":"Tā gǎnmào le, jīntiān bùnéng yùndòng.","j":"彼は風邪をひいたので、今日は運動できません。","e":"He has a cold, so he can't exercise today.","k":"그는 감기에 걸려서 오늘 운동을 할 수 없어요."},{"z":"我腳受傷了，<em>不能</em>走路。","py":"Wǒ jiǎo shòushāng le, bùnéng zǒulù.","j":"私は足をけがしたので、歩けません。","e":"I hurt my foot, so I can't walk.","k":"저는 발을 다쳐서 걸을 수 없어요."}]},
{"id":"g2-035","cat":"助動詞","t":"要1","g":{"j":"もうすぐ〜する","e":"about to (do)","k":"곧 ~하려고 하다"},"p":{"j":"要 + V + 了","e":"yào + V + le","k":"要 + V + 了"},"ex":{"j":"「要+動詞+了」で「もうすぐ〜する」という差し迫った未来を表す。単純な意志の「要」(〜したい)との違いに注意。「了」は必須。","e":"\"要...了\" indicates an imminent action (\"about to happen\"), different from the volitional \"要\" meaning \"want to.\" The \"了\" is essential here.","k":"'要+동사+了'는 '곧 ~하려고 하다'라는 임박한 미래를 나타낸다. 단순한 의지를 뜻하는 '要'(~하고 싶다)와 구별해야 하며 '了'가 반드시 필요하다."},"eg":[{"z":"我<em>要出去了</em>，你有什麼話快一點說吧。","py":"Wǒ yào chūqù le, nǐ yǒu shénme huà kuài yìdiǎn shuō ba.","j":"私はもう出かけるから、言いたいことがあれば早く言って。","e":"I'm about to go out, so if you have something to say, say it quickly.","k":"나 지금 나갈 거니까, 할 말 있으면 빨리 말해."},{"z":"電影<em>要開始了</em>，我們快進去吧。","py":"Diànyǐng yào kāishǐ le, wǒmen kuài jìnqù ba.","j":"映画がもうすぐ始まるから、早く入ろう。","e":"The movie is about to start, let's go in quickly.","k":"영화가 곧 시작하니까 우리 빨리 들어가자."}]},
{"id":"g2-036","cat":"特殊構文","t":"賓+被+V","g":{"j":"〜される(受け身)","e":"be done to (passive)","k":"~되다 (피동)"},"p":{"j":"受事+被+(動作主)+動詞","e":"Object/Patient + 被 (+ Agent) + Verb","k":"대상+被(+동작주)+동사"},"ex":{"j":"「被」は受け身文で使う。動作を受ける物・人を主語にして「主語+被+(動作主)+動詞」の形にする。動詞の後には結果を表す語(了・破など)がよく付く。「把」構文との混同に注意。","e":"The 被 passive puts the affected object/person as subject: Subject + 被 (+ agent) + Verb, often with a resultative ending (了, 破, etc.). Don't confuse it with the 把 construction, which keeps the original subject and moves the object before the verb instead.","k":"「被」는 피동문에 쓰인다. 동작을 당하는 대상을 주어로 삼아 '주어+被(+동작주)+동사' 형태를 만들며 동사 뒤에는 결과를 나타내는 말(了, 破 등)이 자주 붙는다. 주어를 바꾸지 않는 '把' 구문과 헷갈리지 않도록 주의."},"eg":[{"z":"盒子<em>被</em>打開了。","py":"Hézi bèi dǎkāile.","j":"箱が開けられた。","e":"The box was opened.","k":"상자가 열렸다."},{"z":"窗戶<em>被</em>打破了。","py":"Chuānghù bèi dǎpòle.","j":"窓が割られた。","e":"The window was broken.","k":"창문이 깨졌다."}]},
{"id":"g2-037","cat":"補語","t":"V+Vs","g":{"j":"動詞+結果を表す状態動詞","e":"verb + result (stative verb complement)","k":"동사+결과 상태동사"},"p":{"j":"V ＋ Vs(＋了/嗎)","e":"V + Vs (+ 了/嗎)","k":"V＋Vs(＋了/嗎)"},"ex":{"j":"動詞の後ろに状態動詞(飽・完・懂・好など)を続けて、動作の結果や達成度を表す。「動詞+了」だけでは結果が示せない場合に使う。否定は「沒+V+Vs」で、「不」は使わない点に注意。","e":"Attach a stative verb (飽, 完, 懂, 好, etc.) right after the main verb to show the result the action achieved, not just that the action happened. Negate with 沒 + V + Vs, never with 不, since it describes a completed result.","k":"동사 뒤에 상태동사(飽, 完, 懂, 好 등)를 붙여 동작의 결과나 완성 정도를 나타낸다. 단순히 동작만 말하는 '동사+了'와 다르다. 부정은 '不'가 아니라 '沒+V+Vs'로 한다는 점에 주의."},"eg":[{"z":"你吃<em>飽</em>了嗎？","py":"Nǐ chībǎole ma?","j":"もうお腹いっぱいになりましたか?","e":"Are you full? (Have you had enough to eat?)","k":"배부르게 먹었어요?"},{"z":"我做<em>完</em>功課了。","py":"Wǒ zuòwán gōngkèle.","j":"私は宿題をやり終えた。","e":"I finished my homework.","k":"나는 숙제를 다 했다."}]},
{"id":"g2-038","cat":"介詞","t":"跟2","g":{"j":"〜に(動作の相手)","e":"to/with (target of an action)","k":"~에게(동작 대상)"},"p":{"j":"A ＋ 跟 ＋ B ＋ 說/借/商量…","e":"A + 跟 + B + 說/借/商量…","k":"A＋跟＋B＋說/借/商量…"},"ex":{"j":"「跟」はここで動作の相手を導く前置詞。「跟+人+說/借/商量」のように、話す・借りるなどの対象を示す。「一緒に」を表す「跟1」とは違い、ここは動作の向かう相手を表す。","e":"Here 跟 introduces the person a communicative or transactional action is directed at: 跟 + person + 說/借/商量. This differs from the accompaniment sense of 跟 (跟...一起), which marks a companion rather than a target.","k":"여기서 '跟'은 동작의 대상을 이끄는 전치사다. '跟+사람+說/借/商量'처럼 말하거나 빌리는 대상을 나타낸다. 함께함을 뜻하는 '跟1(一起)'과 달리, 동작이 향하는 상대를 가리킨다는 점이 다르다."},"eg":[{"z":"他<em>跟</em>我說了一個很有意思的故事。","py":"Tā gēn wǒ shuōle yí ge hěn yǒuyìsi de gùshì.","j":"彼は私にとても面白い話をしてくれた。","e":"He told me a very interesting story.","k":"그는 나에게 아주 재미있는 이야기를 해 주었다."},{"z":"媽媽<em>跟</em>我借了兩百塊。","py":"Māma gēn wǒ jièle liǎngbǎi kuài.","j":"母は私から二百元借りた。","e":"Mom borrowed NT$200 from me.","k":"엄마는 나에게서 이백 위안을 빌렸다."}]},
{"id":"g2-039","cat":"助動詞","t":"想","g":{"j":"〜したい","e":"want to","k":"~하고 싶다"},"p":{"j":"S ＋ 想 ＋ 動詞(句)","e":"S + 想 + Verb (Phrase)","k":"S＋想＋동사(구)"},"ex":{"j":"「想」は「〜したい」という願望を表す助動詞。「想+動詞(句)」の形で使う。「要」より穏やかで断定的でない言い方。否定は「不想」。","e":"想 is a modal verb meaning 'want to / would like to,' used as 想 + verb (phrase). It sounds softer and less decisive than 要. Negate with 不想, not 沒想.","k":"'想'은 '~하고 싶다'는 바람을 나타내는 조동사로 '想+동사(구)' 형태로 쓴다. '要'보다 부드럽고 덜 단정적인 표현이다. 부정은 '沒想'이 아니라 '不想'으로 한다."},"eg":[{"z":"妹妹<em>想</em>吃冰淇淋。","py":"Mèimei xiǎng chī bīngqílín.","j":"妹はアイスクリームが食べたい。","e":"My little sister wants to eat ice cream.","k":"여동생은 아이스크림을 먹고 싶어 한다."},{"z":"我<em>想</em>喝珍珠奶茶。","py":"Wǒ xiǎng hē zhēnzhū nǎichá.","j":"私はタピオカミルクティーが飲みたい。","e":"I want to drink bubble milk tea.","k":"나는 버블밀크티를 마시고 싶다."}]},
{"id":"g2-040","cat":"介詞","t":"和2","g":{"j":"〜と一緒に","e":"with (someone)","k":"~와 함께"},"p":{"j":"A ＋ 和 ＋ B ＋ 動詞","e":"A + 和 + B + Verb","k":"A＋和＋B＋동사"},"ex":{"j":"「和」はここで「〜と一緒に」を表す前置詞(跟1と同じ用法)。「A+和+B+動詞」の形で、一緒に行動する相手を示す。名詞をつなぐ接続詞の「和」(AとB)とは働きが違うので注意。","e":"Here 和 works like 跟 (accompaniment 'with'): A + 和 + B + verb, naming the person one does something together with. Don't confuse it with the conjunction 和 that simply links two nouns ('A and B').","k":"여기서 '和'는 '~와 함께'를 뜻하는 전치사로(跟1과 같은 용법) 'A+和+B+동사' 형태로 함께 행동하는 상대를 나타낸다. 명사를 연결하는 접속사 '和'(A와 B)와는 기능이 다르니 주의."},"eg":[{"z":"妹妹很喜歡<em>和</em>爸爸聊天。","py":"Mèimei hěn xǐhuān hé bàba liáotiān.","j":"妹はお父さんとおしゃべりするのが大好きだ。","e":"My little sister loves chatting with Dad.","k":"여동생은 아빠와 이야기하는 것을 아주 좋아한다."},{"z":"弟弟常<em>和</em>朋友打籃球。","py":"Dìdi cháng hé péngyǒu dǎ lánqiú.","j":"弟はよく友達とバスケットボールをする。","e":"My little brother often plays basketball with friends.","k":"남동생은 자주 친구와 농구를 한다."}]},
{"id":"g2-041","cat":"介詞","t":"從1","g":{"j":"起點を表す「〜から」","e":"from (a place of origin)","k":"~에서/부터 (출발점)"},"p":{"j":"主語＋從＋場所＋來/動詞","e":"Subject + 從 + place + verb","k":"주어 + 從 + 장소 + 동사"},"ex":{"j":"「從」は動作の出発点(場所・時間)を示す介詞で、必ず場所や時間の語が後ろに続く。到着点を表す「到」と混同しないよう注意。","e":"\"從\" marks the starting point (place or time) of an action and must be followed by a place/time word. Don't confuse it with \"到\", which marks the destination.","k":"\"從\"은 동작의 출발점(장소·시간)을 나타내는 개사로 반드시 뒤에 장소나 시간이 온다. 도착점을 뜻하는 \"到\"와 혼동하지 않도록 주의한다."},"eg":[{"z":"我<em>從</em>法國來。","py":"Wǒ cóng Fǎguó lái.","j":"私はフランスから来ました。","e":"I come from France.","k":"저는 프랑스에서 왔어요."},{"z":"她<em>從</em>美國來，我<em>從</em>日本來。","py":"Tā cóng Měiguó lái, wǒ cóng Rìběn lái.","j":"彼女はアメリカから来て、私は日本から来ました。","e":"She comes from the United States, and I come from Japan.","k":"그녀는 미국에서 왔고, 저는 일본에서 왔어요."}]},
{"id":"g2-042","cat":"介詞","t":"用","g":{"j":"手段・道具を表す「〜で/〜を使って」","e":"using (a tool or means)","k":"~으로/~을 사용해서"},"p":{"j":"主語＋用＋道具＋動詞","e":"Subject + 用 + tool + verb","k":"주어 + 用 + 도구 + 동사"},"ex":{"j":"「用」は動作に使う道具・手段を導く介詞。「用＋名詞」のかたまりを動詞の前に置く。「跟」(〜と)など対象を表す介詞と混同しやすいので注意。","e":"\"用\" introduces the tool or means used to do an action; the \"用 + noun\" phrase goes before the main verb. Don't confuse it with \"跟\" (with, marking a person).","k":"\"用\"은 동작에 사용하는 도구나 수단을 이끄는 개사로 \"用+명사\" 덩어리를 동사 앞에 둔다. 대상을 나타내는 \"跟\"과 혼동하지 않도록 주의한다."},"eg":[{"z":"他會<em>用</em>筷子吃飯。","py":"Tā huì yòng kuàizi chīfàn.","j":"彼は箸を使ってご飯を食べることができます。","e":"He can eat with chopsticks.","k":"그는 젓가락을 사용해서 밥을 먹을 수 있어요."},{"z":"我<em>用</em>手機打電話給媽媽。","py":"Wǒ yòng shǒujī dǎ diànhuà gěi māma.","j":"私は携帯電話でお母さんに電話をかけます。","e":"I call my mom using my cellphone.","k":"저는 휴대폰으로 엄마에게 전화를 걸어요."}]},
{"id":"g2-043","cat":"アスペクト","t":"在2/正在V","g":{"j":"動作の進行「〜している」","e":"progressive aspect: to be doing something","k":"동작의 진행 '~하고 있다'"},"p":{"j":"主語＋(正)在＋動詞","e":"Subject + (zhèng)zài + verb","k":"주어 + (正)在 + 동사"},"ex":{"j":"「(正)在＋動詞」は今まさに進行中の動作を表し、文末に「呢」を添えることもある。否定するときは「不」ではなく「沒(有)」を使う点に注意。","e":"\"(正)在 + verb\" expresses an action happening right now, and \"呢\" can be added at the end. To negate it, use \"沒(有)\", not \"不\".","k":"\"(正)在+동사\"는 지금 진행 중인 동작을 나타내며 문장 끝에 \"呢\"를 붙이기도 한다. 부정할 때는 \"不\"가 아니라 \"沒(有)\"를 쓰는 점에 유의한다."},"eg":[{"z":"學生<em>在</em>踢足球。","py":"Xuéshēng zài tī zúqiú.","j":"学生はサッカーをしています。","e":"The students are playing soccer.","k":"학생이 축구를 하고 있어요."},{"z":"爸爸<em>正在</em>洗車。","py":"Bàba zhèngzài xǐchē.","j":"お父さんは車を洗っています。","e":"Dad is washing the car.","k":"아빠는 세차를 하고 있어요."}]},
{"id":"g2-044","cat":"疑問","t":"呢1","g":{"j":"省略疑問文「〜は?」","e":"question particle: \"what about...?\"","k":"생략 의문 '~는요?'"},"p":{"j":"名詞/代名詞＋呢？","e":"Noun/pronoun + 呢?","k":"명사/대명사 + 呢?"},"ex":{"j":"「呢」は前の話題を受けて「〜はどうですか」と尋ねる省略疑問文を作る。「嗎」の是非疑問とは違い、単独では使えず前の文脈が必要。","e":"\"呢\" forms an elliptical question meaning \"what about...?\" that refers back to something already said. Unlike \"嗎\" (yes/no questions), it can't stand alone without prior context.","k":"\"呢\"는 앞서 언급한 화제를 받아 \"~는요?\"라고 묻는 생략 의문문을 만든다. \"嗎\"와 달리 단독으로 쓸 수 없고 앞 문맥이 필요하다."},"eg":[{"z":"他是德國人，你<em>呢</em>？","py":"Tā shì Déguórén, nǐ ne?","j":"彼はドイツ人です、あなたは?","e":"He's German, what about you?","k":"그는 독일 사람이에요, 당신은요?"},{"z":"我要喝奶茶，你<em>呢</em>？","py":"Wǒ yào hē nǎichá, nǐ ne?","j":"私はミルクティーを飲みたいです、あなたは?","e":"I want to drink milk tea, what about you?","k":"저는 밀크티를 마시고 싶어요, 당신은요?"}]},
{"id":"g2-045","cat":"接続","t":"（雖然），可是","g":{"j":"逆接「〜けれども、しかし〜」","e":"although..., but... (concessive)","k":"비록 ~이지만, 그러나 ~"},"p":{"j":"（雖然）＋A，可是＋B","e":"(Suīrán) + A, kěshì + B","k":"(雖然) + A, 可是 + B"},"ex":{"j":"「雖然」は省略できるが「可是」は省略できない。前半で事実を認め、後半で対照的な内容を述べる。日本語と違い、譲歩節が必ず先に来る。","e":"\"雖然\" can be omitted, but \"可是\" cannot; the first clause concedes a fact and the second contrasts it. The concessive clause always comes first, fixed word order.","k":"\"雖然\"은 생략할 수 있지만 \"可是\"는 생략할 수 없다. 앞절에서 사실을 인정하고 뒷절에서 대조되는 내용을 말하며, 양보절이 항상 먼저 온다."},"eg":[{"z":"<em>雖然</em>他不是很有錢，<em>可是</em>他很快樂。","py":"Suīrán tā bú shì hěn yǒuqián, kěshì tā hěn kuàilè.","j":"彼はあまりお金持ちではないけれど、とても幸せです。","e":"Although he isn't very rich, he is very happy.","k":"그는 그다지 부자는 아니지만, 매우 행복해요."},{"z":"<em>雖然</em>下雨了，<em>可是</em>我們還是去爬山。","py":"Suīrán xiàyǔ le, kěshì wǒmen háishì qù páshān.","j":"雨が降ったけれど、私たちはやっぱり山登りに行きます。","e":"Although it's raining, we're still going hiking.","k":"비가 왔지만, 우리는 그래도 등산을 가요."}]},
{"id":"g2-046","cat":"数量","t":"N+們","g":{"j":"人を表す名詞・代名詞を複数にする","e":"pluralizes nouns/pronouns referring to people","k":"사람을 나타내는 명사·대명사를 복수형으로 만듦"},"p":{"j":"N（人）＋ 們","e":"N (person) + 們","k":"N(사람) + 們"},"ex":{"j":"「們」は人を指す名詞・代名詞につけて複数を表す。物や動物には使わない(×蘋果們)。具体的な数字と一緒には使わない(×三個人們)。","e":"\"們\" attaches to nouns/pronouns referring to people to mark plural. Not used with objects/animals (×蘋果們), nor together with a specific number (×三個人們).","k":"'們'은 사람을 가리키는 명사·대명사에 붙여 복수를 나타낸다. 사물·동물에는 쓰지 않고(×蘋果們), 구체적인 수와 함께 쓰지 않는다(×三個人們)."},"eg":[{"z":"<em>孩子們</em>都在外面玩。","py":"Háizimen dōu zài wàimiàn wán.","j":"子どもたちはみんな外で遊んでいます。","e":"The children are all playing outside.","k":"아이들이 모두 밖에서 놀고 있다."},{"z":"<em>學生們</em>都在教室裡寫功課。","py":"Xuéshēngmen dōu zài jiàoshì lǐ xiě gōngkè.","j":"学生たちはみんな教室で宿題をしています。","e":"The students are all doing homework in the classroom.","k":"학생들은 모두 교실에서 숙제를 하고 있다."}]},
{"id":"g2-047","cat":"アスペクト","t":"開始V","g":{"j":"ある動作を始める","e":"to begin doing an action","k":"어떤 동작을 시작하다"},"p":{"j":"(時間/主語) ＋ 開始 ＋ V","e":"(Time/Subject) + 開始 (start) + V","k":"(시간/주어) + 開始 + V"},"ex":{"j":"「開始」の後に動詞（句）を続けて「〜し始める」を表す。時間を表す語は開始の前に置く。「開始」は単独でも動詞として使える(例: 電影開始了)。","e":"\"開始\" is followed by a verb (phrase) to mean \"start to...\". Time expressions go before 開始. 開始 can also stand alone as a verb (e.g. 電影開始了 \"the movie has started\").","k":"'開始' 뒤에 동사(구)를 이어 '~하기 시작하다'를 나타낸다. 시간을 나타내는 말은 開始 앞에 온다. '開始'는 단독 동사로도 쓸 수 있다(예: 電影開始了)."},"eg":[{"z":"我們十點<em>開始</em>上課。","py":"Wǒmen shí diǎn kāishǐ shàngkè.","j":"私たちは10時に授業が始まります。","e":"We start class at ten o'clock.","k":"우리는 10시에 수업을 시작합니다."},{"z":"我早上七點<em>開始</em>上班。","py":"Wǒ zǎoshang qī diǎn kāishǐ shàngbān.","j":"私は朝7時に仕事を始めます。","e":"I start work at seven in the morning.","k":"나는 아침 7시에 일을 시작합니다."}]},
{"id":"g2-048","cat":"疑問","t":"怎麼","g":{"j":"方法・手段を尋ねる「どうやって」","e":"asking how/by what means","k":"방법·수단을 묻는 '어떻게'"},"p":{"j":"(主語) ＋ 怎麼 ＋ V","e":"(Subject) + 怎麼 (how) + V","k":"(주어) + 怎麼 + V"},"ex":{"j":"「怎麼」は動詞の前に置いて方法・手段(どうやって)を尋ねる。理由を尋ねる「為什麼」と混同しやすいので注意。様子を尋ねる「怎麼樣」とも区別する。","e":"\"怎麼\" precedes a verb to ask about method/means (\"how\"). Easy to confuse with \"為什麼\" (why, asking for a reason). Also distinct from \"怎麼樣\" (how is it, asking about condition/manner).","k":"'怎麼'는 동사 앞에 놓여 방법·수단(어떻게)을 묻는다. 이유를 묻는 '為什麼'와 혼동하기 쉬우니 주의. 상태를 묻는 '怎麼樣'과도 구별해야 한다."},"eg":[{"z":"從這裡到車站<em>怎麼</em>走？","py":"Cóng zhèlǐ dào chēzhàn zěnme zǒu?","j":"ここから駅までどうやって行きますか？","e":"How do I get from here to the station?","k":"여기서 역까지 어떻게 가나요?"},{"z":"這個字<em>怎麼</em>寫？","py":"Zhège zì zěnme xiě?","j":"この字はどうやって書きますか？","e":"How do you write this character?","k":"이 글자는 어떻게 써요?"}]},
{"id":"g2-049","cat":"助動詞","t":"可以2","g":{"j":"能力・可能性を表す「〜できる」","e":"expressing ability/possibility (\"can\")","k":"능력·가능성을 나타내는 '~할 수 있다'"},"p":{"j":"主語 ＋ 可以 ＋ V","e":"Subject + 可以 (can) + V","k":"주어 + 可以 + V"},"ex":{"j":"ここでの「可以」は許可(していい)ではなく、能力や状況が許すかどうか(できる)を表す。この意味では否定に「不可以」ではなく普通「不能」を使う点に注意。","e":"Here \"可以\" doesn't mean permission (\"may\") but ability or whether circumstances allow it (\"can\"). Note that in this sense the negative usually uses \"不能\" rather than \"不可以\".","k":"여기서 '可以'는 허가(해도 된다)가 아니라 능력이나 상황이 허락하는지(할 수 있다)를 나타낸다. 이 의미에서 부정은 보통 '不可以'가 아니라 '不能'을 쓴다는 점에 주의."},"eg":[{"z":"你<em>可以</em>看懂中文菜單嗎？","py":"Nǐ kěyǐ kàndǒng Zhōngwén càidān ma?","j":"あなたは中国語のメニューを読んで理解できますか？","e":"Can you read and understand a Chinese menu?","k":"당신은 중국어 메뉴를 보고 이해할 수 있나요?"},{"z":"她<em>可以</em>自己騎腳踏車去學校。","py":"Tā kěyǐ zìjǐ qí jiǎotàchē qù xuéxiào.","j":"彼女は一人で自転車に乗って学校に行くことができます。","e":"She can ride a bike to school by herself.","k":"그녀는 혼자 자전거를 타고 학교에 갈 수 있어요."}]},
{"id":"g2-050","cat":"疑問","t":"為什麼","g":{"j":"理由を尋ねる「なぜ」","e":"asking for a reason (\"why\")","k":"이유를 묻는 '왜'"},"p":{"j":"(主語) ＋ 為什麼 ＋ VP？","e":"(Subject) + 為什麼 (why) + VP?","k":"(주어) + 為什麼 + VP?"},"ex":{"j":"「為什麼」は理由を尋ねる疑問詞で、主語の前後どちらにも置ける。方法を尋ねる「怎麼」と混同しないよう注意(為什麼＝なぜ、怎麼＝どうやって)。","e":"\"為什麼\" is a question word asking for a reason (\"why\") and can appear before or after the subject. Don't confuse it with \"怎麼\" (asking how/method) — 為什麼 = why, 怎麼 = how.","k":"'為什麼'는 이유를 묻는 의문사로 주어 앞뒤 어디에나 올 수 있다. 방법을 묻는 '怎麼'와 혼동하지 않도록 주의(為什麼=왜, 怎麼=어떻게)."},"eg":[{"z":"你<em>為什麼</em>吃不下飯？","py":"Nǐ wèishénme chībuxià fàn?","j":"あなたはどうしてご飯が食べられないのですか？","e":"Why can't you eat your food?","k":"당신은 왜 밥을 못 먹어요?"},{"z":"你<em>為什麼</em>不接電話？","py":"Nǐ wèishénme bù jiē diànhuà?","j":"あなたはどうして電話に出ないのですか？","e":"Why didn't you answer the phone?","k":"당신은 왜 전화를 안 받아요?"}]},
{"id":"g2-051","cat":"基本文型","t":"給","g":{"j":"あげる/くれる(二重目的語)","e":"to give (double object)","k":"주다(이중목적어)"},"p":{"j":"A ＋ 給 ＋ O(人) ＋ O(物)","e":"A + 給 + Recipient + Thing","k":"A ＋ 給 ＋ 사람 ＋ 사물"},"ex":{"j":"「給」は二重目的語構文で「〜に〜をあげる/くれる」を表す。語順は「給+人+物」で固定され、日本語のように「物を人に」の順にしないよう注意。","e":"\"給\" takes two objects: 給 + recipient + thing given. English speakers sometimes put the thing before the person; Mandarin fixes the order as 給+person+thing.","k":"\"給\"는 이중목적어 구문으로 \"給+사람+사물\" 순서가 고정되어 있다. 한국어 어순(사람에게 사물을)에 이끌려 순서를 바꾸지 않도록 주의한다."},"eg":[{"z":"他<em>給我一本書</em>。","py":"Tā gěi wǒ yì běn shū.","j":"彼は私に本を一冊くれた。","e":"He gave me a book.","k":"그가 나에게 책 한 권을 주었다."},{"z":"我<em>給他一杯咖啡</em>。","py":"Wǒ gěi tā yì bēi kāfēi.","j":"私は彼にコーヒーを一杯あげた。","e":"I gave him a cup of coffee.","k":"나는 그에게 커피 한 잔을 주었다."}]},
{"id":"g2-052","cat":"補語","t":"V見","g":{"j":"〜が見える/聞こえる(結果補語)","e":"see/hear successfully (resultative)","k":"보이다/들리다(결과보어)"},"p":{"j":"V(看/聽/遇...) ＋ 見","e":"V (看/聽/遇...) + 見","k":"V(看/聽/遇...) ＋ 見"},"ex":{"j":"「見」は「看/聽/遇」などの後につく結果補語で、動作の結果として知覚が実現したことを表す。「看」だけでは「見ようとした」動作にすぎないが、「看見」は実際に見えたという結果を含む。","e":"\"見\" attaches to perception verbs (看/聽/遇) as a resultative complement marking that perception actually succeeded. \"看\" alone only describes the action of looking, while \"看見\" confirms something was actually seen.","k":"\"見\"는 看/聽/遇 등의 뒤에 붙는 결과보어로, 지각이 실제로 이루어졌음을 나타낸다. \"看\"만 쓰면 보려는 동작만 나타내지만 \"看見\"는 실제로 보였다는 결과까지 포함한다."},"eg":[{"z":"我<em>看見</em>李明華的腳踏車在樓下。","py":"Wǒ kànjiàn Lǐ Mínghuá de jiǎotàchē zài lóuxià.","j":"私は李明華の自転車が階下にあるのを見た。","e":"I saw Li Minghua's bicycle downstairs.","k":"나는 리밍화의 자전거가 아래층에 있는 것을 보았다."},{"z":"我在捷運站<em>聽見</em>他的聲音。","py":"Wǒ zài jiéyùn zhàn tīngjiàn tā de shēngyīn.","j":"私は捷運の駅で彼の声が聞こえた。","e":"I heard his voice at the MRT station.","k":"나는 지하철역에서 그의 목소리를 들었다."}]},
{"id":"g2-053","cat":"アスペクト","t":"V了2","g":{"j":"〜くなった(状態変化)","e":"change of state","k":"~하게 되었다(상태변화)"},"p":{"j":"VP ＋ 了(状態変化)","e":"VP + 了 (change of state)","k":"VP ＋ 了(상태변화)"},"ex":{"j":"文末の「了2」は動作の完了ではなく「以前と違う新しい状態になった」ことを表す。動詞直後につく「了1」(完了)と混同しやすいが、了2は文末に置かれ状態や性質の変化を示す点が異なる。","e":"Sentence-final \"了\" (了2) signals a new state that differs from before, not completion of an action. It's easy to confuse with the verb-suffix \"了1\" (completion), but 了2 sits at the end and marks a change of state.","k":"문장 끝의 \"了2\"는 동작의 완료가 아니라 이전과 다른 새로운 상태가 되었음을 나타낸다. 동사 뒤에 붙는 \"了1\"(완료)과 혼동하기 쉽지만, 了2는 문장 끝에 위치하며 상태의 변화를 나타낸다는 점이 다르다."},"eg":[{"z":"天氣<em>變了</em>。","py":"Tiānqì biàn le.","j":"天気が変わった。","e":"The weather has changed.","k":"날씨가 변했다."},{"z":"弟弟<em>長高了</em>。","py":"Dìdi zhǎng gāo le.","j":"弟の背が高くなった。","e":"My younger brother has grown taller.","k":"남동생이 키가 커졌다."}]},
{"id":"g2-054","cat":"否定","t":"（請）不要","g":{"j":"〜しないでください(禁止)","e":"please don't (negative command)","k":"~하지 마세요(금지)"},"p":{"j":"(請) ＋ 不要 ＋ VP","e":"(請) + 不要 + VP","k":"(請) ＋ 不要 ＋ VP"},"ex":{"j":"「不要」は禁止を表す否定命令で、前に「請」をつけると丁寧な依頼・注意になる。「別」とほぼ同義だが「別」は話し言葉でより直接的、「請不要」は書き言葉やアナウンスにも使える丁寧な形。","e":"\"不要\" forms a negative command (\"don't...\"); adding \"請\" in front softens it into a polite request or notice. \"不要\" and \"別\" are near-synonyms, but \"別\" feels more direct/colloquial while \"請不要\" is polite enough for written notices.","k":"\"不要\"는 금지를 나타내는 부정명령이며, 앞에 \"請\"을 붙이면 정중한 부탁이나 안내가 된다. \"不要\"와 \"別\"는 거의 같은 뜻이지만 \"別\"는 더 구어적이고 직접적인 반면 \"請不要\"는 문어체나 안내문에도 쓸 수 있는 정중한 표현이다."},"eg":[{"z":"請<em>不要</em>說話！","py":"Qǐng búyào shuōhuà!","j":"話さないでください!","e":"Please don't talk!","k":"제발 말하지 마세요!"},{"z":"請<em>不要</em>在圖書館吃東西。","py":"Qǐng búyào zài túshūguǎn chī dōngxi.","j":"図書館で物を食べないでください。","e":"Please don't eat in the library.","k":"도서관에서 음식을 먹지 마세요."}]},
{"id":"g2-055","cat":"数量","t":"數字+幾","g":{"j":"〜数(概数)","e":"approximately (-odd)","k":"~여(대략적인 수)"},"p":{"j":"數字(十/二十...) ＋ 幾 ＋ 量詞 ＋ N","e":"Round number (十/二十...) + 幾 + Measure + N","k":"숫자(十/二十...) ＋ 幾 ＋ 양사 ＋ N"},"ex":{"j":"「幾」は「十幾・二十幾」のように十の位の数字の後につけて「〜数」という概数を表す。単独の疑問詞「幾」(いくつ)と違い、ここでは疑問の意味はなく、はっきりしないおおよその数量を示す。","e":"Here \"幾\" attaches after a round number (十幾, 二十幾) to mean \"-odd\"/\"more than X\", an approximate quantity — not the interrogative \"幾\" (\"how many?\"). Learners sometimes mistake it for a question.","k":"여기서 \"幾\"는 \"十幾, 二十幾\"처럼 십의 자리 수 뒤에 붙어 \"~여\" 정도의 대략적인 수량을 나타낸다. 의문사 \"幾\"(몇)와 달리 여기서는 의문의 뜻이 없으며 범위가 불명확한 대략적인 수를 가리킨다."},"eg":[{"z":"這條路上有<em>十幾</em>間餐廳。","py":"Zhè tiáo lù shàng yǒu shí jǐ jiān cāntīng.","j":"この道には十数軒のレストランがある。","e":"There are more than ten restaurants on this street.","k":"이 길에는 십여 개의 식당이 있다."},{"z":"他的房間裡有<em>三十幾</em>本書。","py":"Tā de fángjiān lǐ yǒu sānshí jǐ běn shū.","j":"彼の部屋には三十数冊の本がある。","e":"There are more than thirty books in his room.","k":"그의 방에는 삼십여 권의 책이 있다."}]},
{"id":"g2-056","cat":"特殊構文","t":"請","g":{"j":"〜してください","e":"please","k":"~해 주세요"},"p":{"j":"請＋(相手)＋動詞","e":"Qǐng + (person) + Verb","k":"請 + (상대방) + 동사"},"ex":{"j":"「請」は丁寧に依頼・命令する時に動詞や相手の前に置く語で、命令文をやわらげる働きがある。よくある間違いは、質問する時に使う「請問」と混同すること。","e":"\"請\" softens a request or command and is placed before the verb or the addressee. Common mistake: confusing it with \"請問,\" which is used specifically to ask a question politely, not to request an action.","k":"\"請\"은 부탁이나 명령을 공손하게 할 때 동사나 상대방 앞에 씁니다. 질문할 때 쓰는 \"請問\"과 혼동하지 않도록 주의하세요."},"eg":[{"z":"<em>請</em>你走過來。","py":"Qǐng nǐ zǒu guòlái.","j":"こちらへ歩いて来てください。","e":"Please come over here.","k":"이쪽으로 좀 와 주세요."},{"z":"<em>請</em>你安靜一點。","py":"Qǐng nǐ ānjìng yìdiǎn.","j":"少し静かにしてください。","e":"Please be a bit quieter.","k":"조금 조용히 해 주세요."}]},
{"id":"g2-057","cat":"補語","t":"V得+補語","g":{"j":"〜するのが…だ(様態・結果を表す)","e":"do X in a ... way","k":"~하는 것이 …하다(정도・결과)"},"p":{"j":"(V＋O＋)V＋得＋補語","e":"(V+O+) V + 得 + Complement","k":"(V+O+) V+得+보어"},"ex":{"j":"動詞の後に「得」をつけて動作の様子や結果を説明する。目的語がある場合は動詞を繰り返す(V＋O＋V得＋補語)。よくある間違いは「的」「地」と書き間違えること。","e":"\"V得+complement\" describes how an action is done or its result; when there's an object, the verb repeats (V+O+V得+complement). Common mistake: confusing this 得 (de) with 的 (de) or 地 (de), which sound alike but have different grammatical roles.","k":"동사 뒤에 \"得\"를 붙여 동작의 상태나 결과를 설명합니다. 목적어가 있으면 동사를 반복합니다(V+O+V得+보어). \"的\", \"地\"와 발음이 같아 혼동하기 쉬우니 주의하세요."},"eg":[{"z":"王美美的中文字<em>寫得很漂亮</em>。","py":"Wáng Měiměi de Zhōngwén zì xiě de hěn piàoliang.","j":"王美美さんの中国語の字はとてもきれいに書けている。","e":"Wang Meimei's Chinese characters are written very beautifully.","k":"왕메이메이의 중국어 글씨는 아주 예쁘게 쓰여 있다."},{"z":"他說中文<em>說得很流利</em>。","py":"Tā shuō Zhōngwén shuō de hěn liúlì.","j":"彼は中国語をとても流暢に話す。","e":"He speaks Chinese very fluently.","k":"그는 중국어를 아주 유창하게 말한다."}]},
{"id":"g2-058","cat":"特殊構文","t":"幫","g":{"j":"〜のために(手伝って)…する","e":"to help / do something for someone","k":"~을 위해(대신) …하다"},"p":{"j":"幫＋人＋動詞","e":"Bāng + Person + Verb","k":"幫 + 사람 + 동사"},"ex":{"j":"「幫」は「〜のために/〜に代わって」という意味で、「幫＋人＋動詞」の語順を取る。英語の発想で動詞の後に置く間違いに注意。","e":"\"幫\" means to do something for/help someone, in the pattern 幫+person+verb. Common mistake: placing 幫 after the verb (following English \"help me do X\" order) instead of before the person.","k":"\"幫\"은 \"~을 위해/대신해서\"라는 뜻으로 \"幫+사람+동사\" 어순을 씁니다. 영어식으로 동사 뒤에 놓지 않도록 주의하세요."},"eg":[{"z":"你可以<em>幫</em>我去郵局寄信嗎？","py":"Nǐ kěyǐ bāng wǒ qù yóujú jì xìn ma?","j":"私の代わりに郵便局へ行って手紙を出してもらえますか?","e":"Could you go to the post office and mail a letter for me?","k":"저를 대신해서 우체국에 가서 편지를 부쳐 줄 수 있어요?"},{"z":"你可以<em>幫</em>我拿一下那本書嗎？","py":"Nǐ kěyǐ bāng wǒ ná yíxià nà běn shū ma?","j":"ちょっとあの本を取ってもらえますか?","e":"Could you grab that book for me?","k":"그 책 좀 집어 주실 수 있어요?"}]},
{"id":"g2-059","cat":"副詞","t":"以前","g":{"j":"以前・〜する前に","e":"before / in the past","k":"예전에・~하기 전에"},"p":{"j":"以前 / V＋以前","e":"yǐqián / V + yǐqián","k":"以前 / V + 以前"},"ex":{"j":"「以前」は「以前は/〜する前に」という意味。文頭で単独の時間詞として使うほか、「動詞＋以前」で「〜する前に」を表す。反対語「以後」との使い分けに注意。","e":"\"以前\" means \"before/in the past.\" It can stand alone as a time word, or follow a clause as \"before doing X\" (V+以前). Common mistake: mixing it up with its opposite, 以後 (\"after\").","k":"\"以前\"는 \"예전에/~하기 전에\"라는 뜻입니다. 문장 앞에서 단독으로 쓰이거나, \"동사+以前\" 형태로 \"~하기 전에\"를 나타냅니다. 반대말인 \"以後\"와 혼동하지 않도록 주의하세요."},"eg":[{"z":"我<em>以前</em>在醫院工作過。","py":"Wǒ yǐqián zài yīyuàn gōngzuò guò.","j":"私は以前病院で働いたことがある。","e":"I used to work at a hospital.","k":"저는 예전에 병원에서 일한 적이 있어요."},{"z":"我<em>以前</em>不喜歡喝咖啡，現在很喜歡。","py":"Wǒ yǐqián bù xǐhuān hē kāfēi, xiànzài hěn xǐhuān.","j":"私は以前コーヒーが好きではなかったが、今はとても好きだ。","e":"I didn't use to like coffee, but now I like it a lot.","k":"저는 예전에는 커피를 좋아하지 않았는데, 지금은 아주 좋아해요."}]},
{"id":"g2-060","cat":"補語","t":"V出1","g":{"j":"〜し出る・中から外へ","e":"out (directional complement)","k":"~해서 나오다(방향보어)"},"p":{"j":"V＋出＋(場所/物)","e":"V + 出 + (place/object)","k":"V+出+(장소/사물)"},"ex":{"j":"「V出＋場所」で「〜から出る」という動作の方向を表す。「從」を余計に加えたり、視点を示す「出來」と混同したりしないよう注意。","e":"\"V出 + place\" shows movement from inside to outside a location, without needing \"從\" before the place. Common mistake: adding \"從\" redundantly, or confusing plain \"出\" with \"出來,\" which adds a viewpoint toward the speaker.","k":"\"V出+장소\"는 안에서 밖으로 나가는 동작의 방향을 나타내며, 장소 앞에 \"從\"을 따로 붙일 필요가 없습니다. \"從\"을 불필요하게 추가하거나, 화자 쪽을 향하는 \"出來\"와 혼동하지 않도록 주의하세요."},"eg":[{"z":"王美美一<em>走出</em>餐廳就看見室友。","py":"Wáng Měiměi yì zǒuchū cāntīng jiù kànjiàn shìyǒu.","j":"王美美はレストランを出るとすぐにルームメイトを見かけた。","e":"As soon as Wang Meimei walked out of the restaurant, she saw her roommate.","k":"왕메이메이는 식당을 나오자마자 룸메이트를 보았다."},{"z":"他<em>走出</em>教室，去買飲料。","py":"Tā zǒuchū jiàoshì, qù mǎi yǐnliào.","j":"彼は教室を出て、飲み物を買いに行った。","e":"He walked out of the classroom to go buy a drink.","k":"그는 교실을 나가서 음료를 사러 갔다."}]},
{"id":"g2-061","cat":"副詞","t":"多/少","g":{"j":"多く/少なく〜する","e":"do more/less of something","k":"더/덜 ~하다"},"p":{"j":"多/少 ＋ 動詞 (＋ 一點/數量)","e":"duō/shǎo + Verb (+ yìdiǎn/quantity)","k":"多/少 + 동사 (+ 一點/수량)"},"ex":{"j":"「多/少」は動詞の前に置いて「もっと〜する/少なめに〜する」を表す副詞。動詞の後ろに置く間違い(×吃多)に注意。「一點」は動詞の後に添えることが多い。","e":"\"Duō/shǎo\" go before the verb to mean \"do more/less of it.\" A common mistake is placing them after the verb (×吃多); \"yìdiǎn\" usually follows the verb instead.","k":"多/少는 동사 앞에 놓여 \"더/덜 ~하다\"를 나타내는 부사예요. 동사 뒤에 놓는 실수(×吃多)에 주의하고, 一點은 보통 동사 뒤에 붙여요."},"eg":[{"z":"你可以<em>多</em>吃一點水果。","py":"Nǐ kěyǐ duō chī yìdiǎn shuǐguǒ.","j":"果物をもう少し多く食べてもいいですよ。","e":"You can eat a bit more fruit.","k":"과일을 좀 더 먹어도 돼요."},{"z":"你應該<em>少</em>吃甜食。","py":"Nǐ yīnggāi shǎo chī tiánshí.","j":"甘いものは少し控えたほうがいいですよ。","e":"You should eat less sweets.","k":"단 음식을 좀 덜 먹어야 해요."}]},
{"id":"g2-062","cat":"副詞","t":"也","g":{"j":"〜も","e":"also / too","k":"~도"},"p":{"j":"A ＋ 也 ＋ 動詞/形容詞","e":"A + yě + Verb/Adjective","k":"A + 也 + 동사/형용사"},"ex":{"j":"「也」は主語の後・動詞の前に置き、「〜も」を表す副詞。文末に置く間違い(×...日文也)に注意。「都」(全部)と混同しないこと。","e":"\"Yě\" (\"also/too\") goes right before the verb, not at the end of the sentence like English \"too\" (avoid ×...日文也). Don't confuse it with \"dōu\" (\"all/both\").","k":"也는 주어 뒤, 동사 앞에 놓여 \"~도\"를 나타내는 부사예요. 문장 끝에 두는 실수(×...日文也)에 주의하고, \"都\"(모두)와 헷갈리지 마세요."},"eg":[{"z":"他會說中文，<em>也</em>會說日文。","py":"Tā huì shuō Zhōngwén, yě huì shuō Rìwén.","j":"彼は中国語を話せますし、日本語も話せます。","e":"He can speak Chinese, and he can also speak Japanese.","k":"그는 중국어를 할 줄 알고, 일본어도 할 줄 알아요."},{"z":"我喜歡喝咖啡，<em>也</em>喜歡喝茶。","py":"Wǒ xǐhuān hē kāfēi, yě xǐhuān hē chá.","j":"私はコーヒーを飲むのが好きだし、お茶を飲むのも好きです。","e":"I like drinking coffee, and I also like drinking tea.","k":"저는 커피 마시는 것도 좋아하고, 차 마시는 것도 좋아해요."}]},
{"id":"g2-063","cat":"介詞","t":"在3","g":{"j":"〜の時に","e":"at the time of / during","k":"~할 때"},"p":{"j":"在 ＋ 時間・場合 ＋ 的時候","e":"zài + time/occasion + de shíhòu","k":"在 + 시간/상황 + 的時候"},"ex":{"j":"「在＋時間・場合＋的時候」で「〜の時に」を表す。場所を表す「在」(例:在家)や進行を表す「在」(例:在吃飯)と区別すること。「的時候」を忘れる間違いに注意。","e":"\"Zài + time/occasion + de shíhòu\" means \"at the time of / when.\" Don't confuse it with \"zài\" for location (zài jiā) or ongoing action (zài chīfàn). A common mistake is dropping \"de shíhòu.\"","k":"\"在 + 시간/상황 + 的時候\"는 \"~할 때\"를 나타내요. 장소를 나타내는 在(在家)나 진행을 나타내는 在(在吃飯)와 구별하세요. \"的時候\"를 빠뜨리는 실수에 주의하세요."},"eg":[{"z":"他<em>在聖誕節的時候</em>去美國。","py":"Tā zài Shèngdànjié de shíhòu qù Měiguó.","j":"彼はクリスマスの時にアメリカへ行きます。","e":"He goes to the United States at Christmas.","k":"그는 크리스마스 때 미국에 가요."},{"z":"他<em>在放假的時候</em>去日本旅行。","py":"Tā zài fàngjià de shíhòu qù Rìběn lǚxíng.","j":"彼は休みの時に日本へ旅行に行きます。","e":"He goes on a trip to Japan during his vacation.","k":"그는 방학 때 일본으로 여행을 가요."}]},
{"id":"g2-064","cat":"接続","t":"以後","g":{"j":"〜した後","e":"after","k":"~한 후에"},"p":{"j":"動作/時間 ＋ 以後，…","e":"Action/time + yǐhòu, …","k":"동작/시간 + 以後，…"},"ex":{"j":"「以後」は動詞句や時間詞の後に置き、「〜した後」を表す。単独で使う「後來」(その後)と違い、前に基準となる動作や時間が必要。「以前」(前)との対義も覚えること。","e":"\"Yǐhòu\" follows a verb phrase or time word to mean \"after that.\" Unlike \"hòulái\" (afterwards), which can stand alone, \"yǐhòu\" needs a preceding action or time as its anchor. Remember its opposite, \"yǐqián\" (before).","k":"\"以後\"는 동사구나 시간사 뒤에 붙어 \"~한 후\"를 나타내요. 단독으로 쓰는 \"後來\"(그 후)와 달리 앞에 기준이 되는 동작이나 시간이 필요해요. 반대말 \"以前\"(전)도 함께 기억하세요."},"eg":[{"z":"吃完早餐<em>以後</em>，他就去上學了。","py":"Chīwán zǎocān yǐhòu, tā jiù qù shàngxué le.","j":"朝ご飯を食べ終わった後、彼は学校へ行きました。","e":"After finishing breakfast, he went to school.","k":"아침을 다 먹은 후에 그는 학교에 갔어요."},{"z":"下課<em>以後</em>，我要去便利商店買飲料。","py":"Xiàkè yǐhòu, wǒ yào qù biànlìshāngdiàn mǎi yǐnliào.","j":"授業が終わった後、私はコンビニへ飲み物を買いに行きます。","e":"After class, I'm going to go buy a drink at the convenience store.","k":"수업이 끝난 후에 저는 편의점에 음료수를 사러 갈 거예요."}]},
{"id":"g2-065","cat":"疑問","t":"怎麼樣","g":{"j":"どう？/どのように？","e":"how / what... like","k":"어때요?"},"p":{"j":"主語 ＋ (狀態/情況) ＋ 怎麼樣？","e":"Subject + (state/situation) + zěnmeyàng?","k":"주어 + (상태/상황) + 怎麼樣?"},"ex":{"j":"「怎麼樣」は文末に置き、様子や意見を尋ねる。動詞の前に置いて方法を尋ねる「怎麼」(例:怎麼去?)と混同しないこと。","e":"\"Zěnmeyàng\" goes at the end of a sentence to ask for an opinion or description of a state. Don't confuse it with \"zěnme\" (how, asking about method), which goes before the verb (e.g., zěnme qù?).","k":"\"怎麼樣\"는 문장 끝에 놓여 상태나 의견을 물어요. 동사 앞에서 방법을 묻는 \"怎麼\"(예: 怎麼去?)와 헷갈리지 마세요."},"eg":[{"z":"今天天氣<em>怎麼樣</em>？","py":"Jīntiān tiānqì zěnmeyàng?","j":"今日の天気はどうですか?","e":"How's the weather today?","k":"오늘 날씨 어때요?"},{"z":"你覺得這家餐廳<em>怎麼樣</em>？","py":"Nǐ juéde zhè jiā cāntīng zěnmeyàng?","j":"このレストランはどう思いますか?","e":"What do you think of this restaurant?","k":"이 식당 어때요?"}]},
{"id":"g2-066","cat":"疑問","t":"幾/多少1","g":{"j":"「幾」「多少」で数や値段を尋ねる","e":"Asking \"how many/how much\" with 幾 or 多少","k":"幾/多少로 수나 값을 묻기"},"p":{"j":"幾＋量詞／多少＋(量詞)＋名詞","e":"Jǐ + measure word / Duōshao + (measure word) + noun","k":"幾+양사 / 多少+(양사)+명사"},"ex":{"j":"「幾」は答えが10未満など少ない数だと予想する時に使い、後ろに量詞が必要。「多少」は数の大小を問わず使え、量詞は省略できる。値段を聞く時は「多少錢」が定番。","e":"\"Jǐ\" expects a small number (usually under 10) and needs a measure word after it; \"duōshao\" works for any quantity and the measure word is optional. Use \"duōshao qián\" for prices.","k":"幾은 대개 10 미만처럼 적은 수를 예상할 때 쓰며 뒤에 양사가 필요하다. 多少는 수의 크기와 상관없이 쓸 수 있고 양사를 생략할 수 있다. 가격을 물을 땐 多少錢을 쓴다."},"eg":[{"z":"從臺北到臺中，坐火車要<em>幾</em>個小時？","py":"Cóng Táiběi dào Táizhōng, zuò huǒchē yào jǐ ge xiǎoshí?","j":"台北から台中まで、電車で何時間かかりますか。","e":"How many hours does it take to go from Taipei to Taichung by train?","k":"타이베이에서 타이중까지 기차로 몇 시간 걸려요?"},{"z":"這杯咖啡<em>多少</em>錢？","py":"Zhè bēi kāfēi duōshǎo qián?","j":"このコーヒーはいくらですか。","e":"How much is this coffee?","k":"이 커피는 얼마예요?"}]},
{"id":"g2-067","cat":"疑問","t":"怎麼辦","g":{"j":"「どうしよう」と困った時に言う言葉","e":"\"What should [I/we] do?\" — expressing a problem","k":"곤란할 때 쓰는 '어떡하지?'"},"p":{"j":"(主語)＋問題の文，怎麼辦？","e":"(Subject) + problem statement, zěnme bàn?","k":"(주어)+문제 문장, 怎麼辦?"},"ex":{"j":"「怎麼辦」は問題が起きて困った時に単独でも使える決まり文句。「怎麼」＋動詞(どうやって〜する)とは違い、具体的な方法ではなく「どうしよう」という戸惑いや助けを求める気持ちを表す。","e":"\"Zěnme bàn\" is a fixed expression used alone when facing a problem, meaning \"what should I do?\" Unlike \"zěnme\" + verb (asking how to do something), it expresses worry or a request for help, not a method.","k":"怎麼辦은 문제가 생겼을 때 단독으로도 쓰는 관용 표현이다. '怎麼+동사'(어떻게 ~하다)와 달리 구체적 방법이 아니라 당황함이나 도움을 구하는 마음을 나타낸다."},"eg":[{"z":"我今天忘了帶錢，<em>怎麼辦</em>？","py":"Wǒ jīntiān wàng le dài qián, zěnme bàn?","j":"私は今日お金を持ってくるのを忘れました、どうしよう？","e":"I forgot to bring money today, what should I do?","k":"오늘 돈 가져오는 걸 깜빡했어요, 어떡하죠?"},{"z":"我的鑰匙不見了，<em>怎麼辦</em>？","py":"Wǒ de yàoshi bú jiàn le, zěnme bàn?","j":"私の鍵が見当たりません、どうしよう？","e":"My keys are missing, what should I do?","k":"열쇠가 없어졌어요, 어떡하죠?"}]},
{"id":"g2-068","cat":"介詞","t":"跟1","g":{"j":"「〜と」「〜と一緒に」を表す介詞","e":"Preposition meaning \"with\" (accompaniment)","k":"'~와 함께'를 나타내는 전치사"},"p":{"j":"A＋跟＋B＋(一起)＋動詞","e":"A + gēn + B + (yìqǐ) + verb","k":"A+跟+B+(一起)+동사"},"ex":{"j":"「跟」はここでは「〜と一緒に」という同伴を表す介詞で、よく「一起」と組み合わせる。名詞を並べる接続詞の「跟」(AとB)とは働きが違うので混同しないこと。","e":"Here \"gēn\" is a preposition meaning \"with,\" often paired with \"yìqǐ\" (together). Don't confuse it with the conjunction \"gēn\" that simply links two nouns (A and B).","k":"여기서 跟은 '~와 함께'라는 동반을 나타내는 전치사로 一起와 자주 함께 쓰인다. 명사를 나열하는 접속사 跟(A와 B)과는 기능이 다르니 혼동하지 않는다."},"eg":[{"z":"我<em>跟</em>姐姐一起到圖書館借書。","py":"Wǒ gēn jiějie yìqǐ dào túshūguǎn jiè shū.","j":"私は姉と一緒に図書館へ本を借りに行きます。","e":"I go to the library with my older sister to borrow books.","k":"저는 언니와 같이 도서관에 가서 책을 빌려요."},{"z":"我<em>跟</em>同學一起去看電影。","py":"Wǒ gēn tóngxué yìqǐ qù kàn diànyǐng.","j":"私はクラスメートと一緒に映画を見に行きます。","e":"I go to watch a movie with my classmate.","k":"저는 반 친구와 같이 영화를 보러 가요."}]},
{"id":"g2-069","cat":"話しことば","t":"請問","g":{"j":"質問の前につける丁寧な前置き「お尋ねします」","e":"Polite phrase before a question, \"excuse me, may I ask...\"","k":"질문 앞에 붙이는 공손한 표현 '여쭤보겠습니다'"},"p":{"j":"請問＋疑問文","e":"Qǐngwèn + question","k":"請問+의문문"},"ex":{"j":"「請問」は見知らぬ人に質問する時の丁寧な前置きで、文頭に置くだけで良く、答えを要求しない。友達同士のくだけた会話ではあまり使わない。","e":"\"Qǐngwèn\" is a polite opener placed at the start of a question, typically used with strangers or in formal situations; it's rarely used in casual chats with friends.","k":"請問은 낯선 사람에게 질문할 때 문두에 붙이는 공손한 표현이다. 격식 있는 상황에서 주로 쓰이며 친구 사이의 편한 대화에서는 잘 쓰지 않는다."},"eg":[{"z":"<em>請問</em>你叫什麼名字？","py":"Qǐngwèn nǐ jiào shénme míngzi?","j":"すみません、お名前は何ですか。","e":"Excuse me, what is your name?","k":"실례지만, 성함이 어떻게 되세요?"},{"z":"<em>請問</em>洗手間在哪裡？","py":"Qǐngwèn xǐshǒujiān zài nǎlǐ?","j":"すみません、お手洗いはどこですか。","e":"Excuse me, where is the restroom?","k":"실례지만, 화장실이 어디예요?"}]},
{"id":"g2-070","cat":"疑問","t":"好嗎","g":{"j":"文末につけて相手の同意を求める「〜いいですか」","e":"Tag question at the end of a sentence asking for agreement, \"...okay?\"","k":"문장 끝에 붙여 동의를 구하는 '~괜찮아요?'"},"p":{"j":"提案／依頼の文，好嗎？","e":"Suggestion/request + hǎo ma?","k":"제안/부탁 문장, 好嗎?"},"ex":{"j":"「好嗎」は提案や依頼をした後につけて、相手に同意やOKを求める付加疑問。「嗎」だけの一般的な疑問文とは違い、必ず具体的な提案・依頼の後ろに置く。","e":"\"Hǎo ma\" is added after a suggestion or request to ask for agreement, like an English tag question. Unlike a plain yes/no question with \"ma,\" it must follow a concrete proposal or request.","k":"好嗎는 제안이나 부탁 뒤에 붙여 상대의 동의를 구하는 부가의문문이다. 단순 의문문의 嗎와 달리 반드시 구체적인 제안·부탁 뒤에 온다."},"eg":[{"z":"請你再說一次，<em>好嗎</em>？","py":"Qǐng nǐ zài shuō yícì, hǎo ma?","j":"もう一度言ってください、いいですか。","e":"Please say it one more time, okay?","k":"다시 한 번 말씀해 주시겠어요?"},{"z":"我們明天再討論，<em>好嗎</em>？","py":"Wǒmen míngtiān zài tǎolùn, hǎo ma?","j":"私たちは明日また話し合いましょう、いいですか。","e":"Let's discuss it again tomorrow, okay?","k":"우리 내일 다시 이야기해요, 괜찮아요?"}]},
{"id":"g2-071","cat":"疑問","t":"怎麼了","g":{"j":"「〜はどうしたの?」(異常を尋ねる)","e":"\"What's wrong with...?\" (asking what happened)","k":"~한테 무슨 일 있어? (이상한 상황을 물음)"},"p":{"j":"人 ＋ 怎麼了？","e":"person + zěnme le?","k":"사람 + 怎麼了?"},"ex":{"j":"「怎麼了」は相手や第三者の様子がいつもと違う時に「どうしたの?」と尋ねる表現。単に感想を聞く「怎麼樣」とは違い、異常や問題の発生を前提とする。","e":"\"Zěnme le\" asks what's wrong when something seems off, unlike \"zěnme yàng,\" which just asks for an opinion or how something turned out. Don't mix the two up.","k":"\"怎麼了\"는 상대방이나 제3자의 상태가 평소와 다를 때 \"무슨 일이야?\"라고 묻는 표현이다. 단순히 의견을 묻는 \"怎麼樣\"과 다르니 혼동하지 말 것."},"eg":[{"z":"李明華今天沒來上班，<em>他怎麼了</em>？","py":"Lǐ Mínghuá jīntiān méi lái shàngbān, tā zěnme le?","j":"李明華は今日仕事に来なかった。彼はどうしたの?","e":"Li Minghua didn't come to work today. What happened to him?","k":"리밍화가 오늘 출근하지 않았어요. 그 사람 무슨 일 있어요?"},{"z":"你的臉色看起來不太好，<em>你怎麼了</em>？","py":"Nǐ de liǎnsè kàn qǐlái bú tài hǎo, nǐ zěnme le?","j":"あなたの顔色があまり良くないね。どうしたの?","e":"You don't look so well. What's wrong?","k":"안색이 별로 안 좋아 보이는데, 무슨 일 있어요?"}]},
{"id":"g2-072","cat":"補語","t":"V到2/在","g":{"j":"動詞+到/在で「動作の結果いる場所」を表す","e":"verb + dào/zài indicating the resulting location of an action","k":"동사+到/在로 동작의 결과 장소를 나타냄"},"p":{"j":"V ＋ 到 ＋ 場所(＋去/來)／V ＋ 在 ＋ 場所","e":"V + dào + place (+ qù/lái) / V + zài + place","k":"V + 到 + 장소(+去/來) / V + 在 + 장소"},"ex":{"j":"「V到+場所」は移動して目的地に到達したことを表し、後に「去/來」を伴うことが多い。「V在+場所」は動作の結果その場所に留まる/存在することを表す。「到」を使うべき移動の場面で「在」を使う、あるいはその逆の誤りが多い。","e":"\"V + dào + place\" shows movement reaching a destination (often followed by qù/lái), while \"V + zài + place\" shows the resulting static location of an action. A common mistake is swapping the two — using zài for movement or dào for a fixed location.","k":"\"V到+장소\"는 이동해서 목적지에 도착했음을 나타내며 뒤에 去/來가 자주 붙는다. \"V在+장소\"는 동작의 결과로 그 장소에 머무는 것을 나타낸다. 이동 상황에 在를, 고정된 위치에 到를 쓰는 실수가 많다."},"eg":[{"z":"阿姨<em>走到</em>對面的超市去買菜。","py":"Āyí zǒu dào duìmiàn de chāoshì qù mǎi cài.","j":"おばさんは向かいのスーパーまで歩いて行って野菜を買う。","e":"Auntie walks over to the supermarket across the street to buy groceries.","k":"아주머니는 맞은편 슈퍼마켓까지 걸어가서 장을 봐요."},{"z":"我朋友一直<em>住在</em>高雄。","py":"Wǒ péngyǒu yìzhí zhù zài Gāoxióng.","j":"私の友達はずっと高雄に住んでいる。","e":"My friend has always lived in Kaohsiung.","k":"제 친구는 계속 가오슝에 살고 있어요."}]},
{"id":"g2-073","cat":"介詞","t":"從......到......1","g":{"j":"「〜から〜まで」(時間の範囲)","e":"\"from... to...\" (time range)","k":"~부터 ~까지 (시간 범위)"},"p":{"j":"從 ＋ 時間A ＋ 到 ＋ 時間B","e":"cóng + time A + dào + time B","k":"從 + 시간A + 到 + 시간B"},"ex":{"j":"時間の始まりと終わりをセットで示す表現。場所の範囲を示す「從...到...2」と形は同じだが、こちらは時間にのみ使う。「從」を省略したり「到」だけで済ませたりする誤りに注意。","e":"This marks a time span from start to end. It shares the same pattern as \"cóng...dào...2,\" but that one is for distance/place, not time. A common mistake is dropping \"cóng\" and using only \"dào.\"","k":"시작과 끝 시간을 한 세트로 나타내는 표현. 장소 범위를 나타내는 \"從...到...2\"와 형태는 같지만 이것은 시간에만 쓴다. \"從\"을 생략하고 \"到\"만 쓰는 실수에 주의."},"eg":[{"z":"這間公司的上班時間是<em>從早上八點到下午五點</em>。","py":"Zhè jiān gōngsī de shàngbān shíjiān shì cóng zǎoshang bā diǎn dào xiàwǔ wǔ diǎn.","j":"この会社の勤務時間は朝8時から午後5時までです。","e":"This company's working hours are from 8 a.m. to 5 p.m.","k":"이 회사의 근무 시간은 아침 8시부터 오후 5시까지예요."},{"z":"圖書館<em>從星期一到星期五</em>都開門。","py":"Túshūguǎn cóng xīngqíyī dào xīngqíwǔ dōu kāimén.","j":"図書館は月曜日から金曜日まで開いている。","e":"The library is open from Monday to Friday.","k":"도서관은 월요일부터 금요일까지 문을 열어요."}]},
{"id":"g2-074","cat":"介詞","t":"從......到......2","g":{"j":"「〜から〜まで」(場所・距離の範囲)","e":"\"from... to...\" (place/distance range)","k":"~에서 ~까지 (장소·거리 범위)"},"p":{"j":"從 ＋ 場所A ＋ 到 ＋ 場所B","e":"cóng + place A + dào + place B","k":"從 + 장소A + 到 + 장소B"},"ex":{"j":"出発地から目的地までの区間を示す。時間の範囲を表す「從...到...1」と構造は同じだが、こちらは場所や距離に使う。所要時間を表す文とセットで使われることが多い。","e":"This marks a route from a starting place to a destination. It has the same structure as \"cóng...dào...1\" but is used for place/distance, often paired with a clause stating how long it takes.","k":"출발지에서 목적지까지의 구간을 나타낸다. 시간 범위를 나타내는 \"從...到...1\"와 구조는 같지만 이것은 장소·거리에 쓰며, 걸리는 시간을 나타내는 문장과 함께 쓰이는 경우가 많다."},"eg":[{"z":"<em>從臺北到南投</em>開車要三個半小時。","py":"Cóng Táiběi dào Nántóu kāichē yào sān ge bàn xiǎoshí.","j":"台北から南投まで車で3時間半かかる。","e":"It takes three and a half hours to drive from Taipei to Nantou.","k":"타이베이에서 난터우까지 차로 3시간 반 걸려요."},{"z":"<em>從我家到學校</em>騎腳踏車大概二十分鐘。","py":"Cóng wǒ jiā dào xuéxiào qí jiǎotàchē dàgài èrshí fēnzhōng.","j":"私の家から学校まで自転車で大体20分だ。","e":"It's about twenty minutes by bike from my house to school.","k":"우리 집에서 학교까지 자전거로 대략 20분 걸려요."}]},
{"id":"g2-075","cat":"副詞","t":"都1","g":{"j":"「みんな/すべて〜」(全体をまとめる副詞)","e":"\"all/both\" (adverb summarizing the whole subject)","k":"모두/다 (전체를 아우르는 부사)"},"p":{"j":"主語(複数) ＋ 都 ＋ 動詞/形容詞","e":"plural subject + dōu + verb/adjective","k":"복수 주어 + 都 + 동사/형용사"},"ex":{"j":"「都」は必ず主語の後、動詞の前に置き、前に出た複数の対象すべてに当てはまることを示す。単数の人やものには使えない点、また主語の前に置く誤りに注意。","e":"\"Dōu\" always sits after the subject and before the verb, showing that something applies to every member of a plural subject. It can't be used with a single person/item, and learners often mistakenly place it before the subject.","k":"\"都\"는 반드시 주어 뒤, 동사 앞에 위치하며 앞에 나온 복수 대상 전체에 해당함을 나타낸다. 단수 대상에는 쓸 수 없고, 주어 앞에 놓는 실수가 흔하다."},"eg":[{"z":"我們<em>都</em>喜歡慢跑。","py":"Wǒmen dōu xǐhuān mànpǎo.","j":"私たちはみんなジョギングが好きだ。","e":"We all like jogging.","k":"우리는 모두 조깅을 좋아해요."},{"z":"他們<em>都</em>是台灣人。","py":"Tāmen dōu shì Táiwānrén.","j":"彼らはみんな台湾人だ。","e":"They are all Taiwanese.","k":"그들은 모두 대만 사람이에요."}]},
{"id":"g2-076","cat":"補語","t":"V來/去1","g":{"j":"來/去で動作の方向を表す","e":"expresses direction with lái/qù","k":"來/去로 동작의 방향을 나타냄"},"p":{"j":"V ＋ 來/去","e":"V + lái/qù","k":"V ＋ 來/去"},"ex":{"j":"「來」は話し手に近づく動作、「去」は話し手から離れる動作を表し、動詞の直後につける。方向補語「進來/出去」などと混同しないよう注意。","e":"\"Lái\" marks movement toward the speaker and \"qù\" marks movement away, attached right after the verb. Don't confuse this with compound directional complements like \"進來/出去\".","k":"來는 화자 쪽으로, 去는 화자에게서 멀어지는 동작을 나타내며 동사 바로 뒤에 붙는다. 進來/出去 같은 복합방향보어와 혼동하지 않도록 주의."},"eg":[{"z":"你的東西我<em>拿來</em>了。","py":"Nǐ de dōngxi wǒ ná lái le.","j":"あなたの物を私が持ってきました。","e":"I brought your things here.","k":"당신의 물건을 제가 가져왔어요."},{"z":"他先<em>跑去</em>買東西了。","py":"Tā xiān pǎo qù mǎi dōngxi le.","j":"彼は先に買い物に行きました。","e":"He went ahead to buy something.","k":"그는 먼저 뛰어가서 물건을 샀어요."}]},
{"id":"g2-077","cat":"接続","t":"因為......所以......","g":{"j":"原因と結果を表す","e":"expresses cause and result","k":"원인과 결과를 나타냄"},"p":{"j":"因為＋原因，所以＋結果","e":"Yīnwèi + reason, suǒyǐ + result","k":"因為＋원인，所以＋결과"},"ex":{"j":"「因為」は原因、「所以」は結果を導く。話し言葉では片方だけ使うことも多いが、書き言葉では両方そろえて書くのが基本形。","e":"\"Yīnwèi\" introduces the reason and \"suǒyǐ\" the result; in speech only one of the two is often used, but written Chinese typically keeps both.","k":"因為는 원인을, 所以는 결과를 이끈다. 회화에서는 둘 중 하나만 쓰는 경우가 많지만 글말에서는 보통 둘 다 함께 쓴다."},"eg":[{"z":"<em>因為</em>他們沒有錢，<em>所以</em>不能出國旅行。","py":"Yīnwèi tāmen méiyǒu qián, suǒyǐ bù néng chūguó lǚxíng.","j":"彼らはお金がないので、海外旅行に行けません。","e":"Because they don't have money, they can't travel abroad.","k":"그들은 돈이 없어서 해외여행을 갈 수 없어요."},{"z":"<em>因為</em>明天要考試，<em>所以</em>我今天晚上要在家讀書。","py":"Yīnwèi míngtiān yào kǎoshì, suǒyǐ wǒ jīntiān wǎnshang yào zài jiā dúshū.","j":"明日試験があるので、私は今晩家で勉強します。","e":"Because there's a test tomorrow, I'm going to study at home tonight.","k":"내일 시험이 있어서 저는 오늘 저녁에 집에서 공부할 거예요."}]},
{"id":"g2-078","cat":"特殊構文","t":"有的......有的......","g":{"j":"全体の中の一部ずつを列挙する","e":"lists different portions of a whole","k":"전체 중 일부씩 열거함"},"p":{"j":"（全體）有的...，有的...","e":"(whole), yǒude..., yǒude...","k":"（전체）有的...，有的..."},"ex":{"j":"全体をいくつかのグループに分けて、それぞれの特徴を並べて言うときに使う。「有的人」のように名詞を省略した形もよく使われ、グループは2つ以上でもよい。","e":"Used to divide a whole into groups and describe each one's trait; often appears without the following noun (\"yǒude rén\" shortened to \"yǒude\"), and can list more than two groups.","k":"전체를 몇 개의 그룹으로 나누어 각각의 특징을 나열할 때 쓴다. 뒤에 오는 명사를 생략한 형태로도 자주 쓰이며 그룹은 두 개 이상이어도 된다."},"eg":[{"z":"班上的同學<em>有的</em>會說英文，<em>有的</em>會說法文。","py":"Bānshàng de tóngxué yǒude huì shuō Yīngwén, yǒude huì shuō Fǎwén.","j":"クラスメートの中には英語が話せる人もいれば、フランス語が話せる人もいます。","e":"Some of the classmates can speak English, and some can speak French.","k":"반 친구들 중에는 영어를 할 줄 아는 사람도 있고 프랑스어를 할 줄 아는 사람도 있어요."},{"z":"這些水果<em>有的</em>很甜，<em>有的</em>很酸。","py":"Zhèxiē shuǐguǒ yǒude hěn tián, yǒude hěn suān.","j":"これらの果物は甘いものもあれば、酸っぱいものもあります。","e":"Some of these fruits are sweet, and some are sour.","k":"이 과일들 중에는 단 것도 있고 신 것도 있어요."}]},
{"id":"g2-079","cat":"介詞","t":"到......（去/來）+VP","g":{"j":"移動先を示してから動作を続ける","e":"indicates the destination before continuing with an action","k":"이동 장소를 나타낸 뒤 동작을 이어감"},"p":{"j":"到＋場所＋去/來＋VP","e":"dào + place + qù/lái + VP","k":"到＋장소＋去/來＋VP"},"ex":{"j":"「到」で目的地を示し、「去/來」で方向をつけてから後ろの動作(VP)を言う。「去＋場所＋VP」(例:去學校上課)と違い、場所の前に必ず「到」が要る点に注意。","e":"\"Dào\" marks the destination, \"qù/lái\" adds direction, then the action (VP) follows. Unlike \"qù + place + VP\" (e.g. qù xuéxiào shàngkè), this pattern requires \"dào\" before the place.","k":"到로 목적지를 나타내고 去/來로 방향을 더한 뒤 이어지는 동작(VP)을 말한다. \"去+장소+VP\"(예: 去學校上課)와 달리 장소 앞에 반드시 到가 와야 한다는 점에 주의."},"eg":[{"z":"你要<em>到哪裡去</em>旅行？","py":"Nǐ yào dào nǎlǐ qù lǚxíng?","j":"あなたはどこへ旅行に行きますか。","e":"Where are you going to travel to?","k":"당신은 어디로 여행을 갈 거예요?"},{"z":"我明天要<em>到台北去</em>開會。","py":"Wǒ míngtiān yào dào Táiběi qù kāihuì.","j":"私は明日台北へ会議に行きます。","e":"I'm going to Taipei tomorrow for a meeting.","k":"저는 내일 타이베이로 회의를 하러 가요."}]},
{"id":"g2-080","cat":"副詞","t":"太Vs了","g":{"j":"程度が過度であることを表す","e":"expresses an excessive degree","k":"정도가 지나침을 나타냄"},"p":{"j":"太＋形容詞＋了","e":"tài + adjective + le","k":"太＋형용사＋了"},"ex":{"j":"程度が高すぎて好ましくない、という話し手の評価を表す。単に程度を言う「很Vs」と違い、「太Vs了」はマイナスの含みを持つことが多い。","e":"Expresses that a degree is excessive, often with a negative nuance. Unlike neutral \"hěn + adj\", \"tài + adj + le\" usually implies the speaker disapproves.","k":"정도가 지나쳐 바람직하지 않다는 화자의 평가를 나타낸다. 단순히 정도를 말하는 \"很+형용사\"와 달리 \"太+형용사+了\"는 부정적인 뉘앙스를 담는 경우가 많다."},"eg":[{"z":"這家飯店<em>太貴了</em>，我不要住。","py":"Zhè jiā fàndiàn tài guì le, wǒ bú yào zhù.","j":"このホテルは高すぎるので、泊まりたくありません。","e":"This hotel is too expensive, I don't want to stay here.","k":"이 호텔은 너무 비싸서 묵고 싶지 않아요."},{"z":"這件衣服<em>太小了</em>，我穿不下。","py":"Zhè jiàn yīfú tài xiǎo le, wǒ chuān bú xià.","j":"この服は小さすぎて、私は着られません。","e":"This piece of clothing is too small, I can't fit into it.","k":"이 옷은 너무 작아서 저는 입을 수가 없어요."}]},
{"id":"g2-081","cat":"疑問","t":"......還是......","g":{"j":"選択疑問文「〜それとも〜」","e":"or (in questions offering a choice)","k":"선택 의문문 '~아니면~'"},"p":{"j":"A ＋ 還是 ＋ B","e":"A + háishì + B","k":"A + 還是 + B"},"ex":{"j":"「還是」は疑問文の中で二択を尋ねる時に使う。「或者」と違い、還是は疑問文専用で平叙文には使えない点に注意。","e":"'還是' offers a choice inside a question ('A or B?'); unlike '或者', which links options in statements, '還是' is used only in questions.","k":"'還是'는 의문문에서 두 가지 중 하나를 고를 때 쓴다. 평서문에서 선택을 나타내는 '或者'와 혼동하지 않도록 주의."},"eg":[{"z":"爸爸今天晚上想<em>吃飯還是吃麵</em>？","py":"Bàba jīntiān wǎnshang xiǎng chī fàn háishì chī miàn?","j":"お父さんは今晩、ご飯が食べたい?それとも麺が食べたい?","e":"Does Dad want to eat rice or noodles tonight?","k":"아빠는 오늘 저녁에 밥을 먹고 싶어요, 아니면 국수를 먹고 싶어요?"},{"z":"你要<em>喝咖啡還是喝茶</em>？","py":"Nǐ yào hē kāfēi háishì hē chá?","j":"コーヒーを飲みたい?それともお茶を飲みたい?","e":"Do you want to drink coffee or tea?","k":"커피 마실래요, 아니면 차 마실래요?"}]},
{"id":"g2-082","cat":"副詞","t":"又......又......","g":{"j":"〜でもあり〜でもある(二つの性質を並べる)","e":"both... and... (two simultaneous qualities)","k":"~하기도 하고 ~하기도 하다"},"p":{"j":"又 ＋ Adj/V1 ＋ 又 ＋ Adj/V2","e":"yòu + Adj/V1 + yòu + Adj/V2","k":"又 + 형용사/동사1 + 又 + 형용사/동사2"},"ex":{"j":"同じ主語が持つ二つの性質や状態を同時に述べる時に使う。「又」は必ず対で使い、片方だけでは使えない。形容詞や動詞の直前に置く。","e":"Used to state two qualities or actions of the same subject at once; '又' always appears in a pair (never alone) and sits directly before each adjective or verb.","k":"같은 주어가 지닌 두 가지 성질이나 상태를 동시에 말할 때 쓴다. '又'는 항상 짝으로 쓰이며 하나만 쓸 수 없다."},"eg":[{"z":"這家餐廳<em>又便宜又有名</em>。","py":"Zhè jiā cāntīng yòu piányí yòu yǒumíng.","j":"このレストランは安くて有名だ。","e":"This restaurant is both cheap and famous.","k":"이 식당은 싸기도 하고 유명하기도 하다."},{"z":"這杯珍珠奶茶<em>又甜又好喝</em>。","py":"Zhè bēi zhēnzhū nǎichá yòu tián yòu hǎohē.","j":"このタピオカミルクティーは甘くて美味しい。","e":"This bubble tea is both sweet and delicious.","k":"이 버블티는 달콤하고 맛있다."}]},
{"id":"g2-083","cat":"副詞","t":"有（一）點Vs","g":{"j":"少し〜(好ましくない状態を控えめに言う)","e":"a little / somewhat (usually negative nuance)","k":"조금 ~하다(대개 부정적 뉘앙스)"},"p":{"j":"有（一）點 ＋ 形容詞","e":"yǒu (yì)diǎn + Adjective","k":"有（一）點 + 형용사"},"ex":{"j":"「有點」は形容詞の前に置き、望ましくない状態を控えめに表す。程度副詞「很」と違い、後ろには通常マイナスの意味の形容詞が来る。","e":"'有點' goes before an adjective to soften an undesirable state; unlike the degree adverb '很', it is typically followed by a negative-leaning adjective, not a positive one.","k":"'有點'은 형용사 앞에 놓여 바람직하지 않은 상태를 완곡하게 나타낸다. 정도부사 '很'과 달리 뒤에는 보통 부정적인 뉘앙스의 형용사가 온다."},"eg":[{"z":"我<em>有一點累</em>。","py":"Wǒ yǒu yìdiǎn lèi.","j":"私はちょっと疲れた。","e":"I'm a little tired.","k":"나는 조금 피곤하다."},{"z":"這件衣服<em>有點貴</em>。","py":"Zhè jiàn yīfú yǒudiǎn guì.","j":"この服はちょっと高い。","e":"This piece of clothing is a bit expensive.","k":"이 옷은 조금 비싸다."}]},
{"id":"g2-084","cat":"特殊構文","t":"（在） PW 的 N","g":{"j":"場所＋的＋名詞(〜にある/にいる…)","e":"(at) place + 的 + noun — the one located at ...","k":"장소+的+명사(~에 있는 …)"},"p":{"j":"(在) ＋ PW ＋ 的 ＋ N","e":"(zài) + Place Word + de + Noun","k":"(在) + 장소어 + 的 + 명사"},"ex":{"j":"場所を表す言葉を「的」で名詞の前に置き、「〜にある(いる)N」という意味を作る。「在」は省略できるが、語順(PW+的+N)は変わらない。","e":"A place word plus '的' modifies a following noun to mean 'the N that is at/in [place]'; '在' can be dropped, but the order (place + 的 + N) stays fixed.","k":"장소를 나타내는 말 뒤에 '的'를 붙여 명사를 꾸미면 '~에 있는 N'이라는 뜻이 된다. '在'는 생략할 수 있지만 어순(장소+的+명사)은 그대로 유지된다."},"eg":[{"z":"<em>在桌上的電腦</em>是我弟弟的。","py":"Zài zhuōshàng de diànnǎo shì wǒ dìdi de.","j":"机の上にあるパソコンは私の弟のものだ。","e":"The computer on the desk is my younger brother's.","k":"책상 위에 있는 컴퓨터는 내 남동생 것이다."},{"z":"<em>在冰箱裡的蛋糕</em>是媽媽做的。","py":"Zài bīngxiāng lǐ de dàngāo shì māma zuò de.","j":"冷蔵庫の中にあるケーキは母が作ったものだ。","e":"The cake in the fridge was made by Mom.","k":"냉장고 안에 있는 케이크는 엄마가 만든 것이다."}]},
{"id":"g2-085","cat":"介詞","t":"從2","g":{"j":"〜から(時間の起点)","e":"from/since (a starting point in time)","k":"~부터(시간의 시작점)"},"p":{"j":"從 ＋ 時間點 ＋ 開始","e":"cóng + Time Point + kāishǐ","k":"從 + 시간 + 開始"},"ex":{"j":"「從」は時間の起点を表し、「開始」と合わせて「〜から始まって」という意味になる。場所の起点を表す從1(從+場所)と混同しないよう注意。","e":"'從' marks a starting point in time, often paired with '開始' ('starting from...'); don't confuse this with 從1, which marks a starting point in space (從 + place).","k":"'從'은 시간의 시작점을 나타내며 '開始'와 함께 써서 '~부터 시작해서'라는 뜻이 된다. 장소의 시작점을 나타내는 從1(從+장소)과 혼동하지 않도록 주의."},"eg":[{"z":"<em>從早上開始</em>，郵局排隊的人就很多。","py":"Cóng zǎoshang kāishǐ, yóujú páiduì de rén jiù hěn duō.","j":"朝から、郵便局に並ぶ人がとても多い。","e":"Starting in the morning, there are already a lot of people lining up at the post office.","k":"아침부터 우체국에 줄 서는 사람이 아주 많다."},{"z":"<em>從下個月開始</em>，我要每天運動。","py":"Cóng xià ge yuè kāishǐ, wǒ yào měitiān yùndòng.","j":"来月から、私は毎日運動するつもりだ。","e":"Starting next month, I'm going to exercise every day.","k":"다음 달부터 나는 매일 운동할 것이다."}]},
{"id":"g2-086","cat":"補語","t":"V起來1","g":{"j":"下から上への動作(立ち上がる)","e":"upward/rising movement (get up, stand up)","k":"아래에서 위로 하는 동작(일어나다)"},"p":{"j":"V＋起來(站起來、坐起來など)","e":"V + 起來 (e.g. 站起來, 坐起來)","k":"V + 起來(站起來, 坐起來 등)"},"ex":{"j":"「起來」は動作が下から上へ完了することを表す。「看起來」など「〜のようだ」を表すV起來(別の語法點)と混同しないよう注意。","e":"Here \"起來\" marks a movement from a lower position to a higher one, completing the verb's direction (e.g. standing up). Don't confuse it with the other \"V起來\" meaning \"it seems/looks\" (看起來).","k":"여기서 \"起來\"는 아래에서 위로 움직이는 동작의 완료를 나타낸다. \"看起來\"처럼 \"~해 보이다\"라는 뜻과 혼동하지 않도록 주의한다."},"eg":[{"z":"他<em>站起來</em>走出房間。","py":"Tā zhàn qǐlai zǒuchū fángjiān.","j":"彼は立ち上がって部屋を出て行った。","e":"He stood up and walked out of the room.","k":"그는 일어나서 방을 나갔다."},{"z":"小狗一聽到腳步聲就<em>跳起來</em>。","py":"Xiǎogǒu yì tīngdào jiǎobùshēng jiù tiàoqǐlai.","j":"子犬は足音を聞くとすぐに飛び上がる。","e":"The puppy jumps up as soon as it hears footsteps.","k":"강아지는 발소리를 듣자마자 벌떡 뛰어오른다."}]},
{"id":"g2-087","cat":"数量","t":"Vs一點","g":{"j":"「もう少し〜して」(程度をやや強める依頼)","e":"\"a bit more ~\" (a mild request for more of a quality)","k":"\"좀 더 ~하게\"(정도를 살짝 강조하는 요청)"},"p":{"j":"Vs(形容詞)＋一點","e":"Stative verb (adjective) + 一點","k":"형용사(Vs) + 一點"},"ex":{"j":"形容詞の後に「一點」を置き、「もう少し〜して」と控えめに程度の変化を求める。比較対象を示す「比…一點」とは違い、ここには比較相手がない。","e":"Adding \"一點\" after an adjective softly asks for a bit more of that quality (often advice or a mild command). This differs from the comparative \"比…一點\", which needs an explicit point of comparison.","k":"형용사 뒤에 \"一點\"을 붙여 \"좀 더 ~하게\"라고 부드럽게 요청한다. 비교 대상이 필요한 \"比…一點\"과 달리 여기에는 비교 상대가 없다."},"eg":[{"z":"搬家的時候要<em>小心一點</em>。","py":"Bānjiā de shíhòu yào xiǎoxīn yìdiǎn.","j":"引っ越しのときはもう少し気をつけてください。","e":"Be a bit more careful when moving house.","k":"이사할 때는 좀 더 조심해야 해요."},{"z":"你說話<em>小聲一點</em>,妹妹在睡覺。","py":"Nǐ shuōhuà xiǎoshēng yìdiǎn, mèimei zài shuìjiào.","j":"もう少し小さい声で話して,妹が寝ているから。","e":"Speak a little more quietly — my sister is sleeping.","k":"좀 더 작은 소리로 말해, 여동생이 자고 있어."}]},
{"id":"g2-088","cat":"数量","t":"數詞+多（量詞）","g":{"j":"「〜より少し多い」(数詞+多+量詞)","e":"\"a bit more than [number]\" (number + 多 + measure word)","k":"\"~보다 조금 많은\"(수사+多+양사)"},"p":{"j":"數詞＋多＋量詞(一個多小時、兩萬多塊)","e":"Number + 多 + measure word (一個多小時, 兩萬多塊)","k":"수사 + 多 + 양사(一個多小時, 兩萬多塊)"},"ex":{"j":"「多」は数字と量詞の間に置き、「その数より少し多い」ことを表す(例:一個多小時=1時間ちょっと)。「數詞＋多＋量詞」の語順を崩さないこと。","e":"\"多\" sits between the number and the measure word to mean \"a bit more than that number\" (e.g. 一個多小時 = a bit over an hour). Keep the order Number + 多 + measure word — don't say \"多一個小時\".","k":"\"多\"는 숫자와 양사 사이에 놓여 \"그 수보다 조금 많음\"을 나타낸다(예: 一個多小時=한 시간 남짓). 어순 \"수사+多+양사\"를 지켜야 하며 \"多一個小時\"처럼 쓰지 않는다."},"eg":[{"z":"他們聊天聊了<em>一個多小時</em>。","py":"Tāmen liáotiān liáo le yí ge duō xiǎoshí.","j":"彼らは1時間あまりおしゃべりをした。","e":"They chatted for over an hour.","k":"그들은 한 시간 넘게 수다를 떨었다."},{"z":"這台筆電花了我<em>兩萬多塊</em>。","py":"Zhè tái bǐdiàn huāle wǒ liǎngwàn duō kuài.","j":"このノートパソコンは2万元あまりかかった。","e":"This laptop cost me over twenty thousand NT dollars.","k":"이 노트북은 2만 대만달러 넘게 들었다."}]},
{"id":"g2-089","cat":"補語","t":"V到1","g":{"j":"「〜まで」(動作がある時点や場所まで続く)","e":"\"until/up to ~\" (an action continues to a point in time or place)","k":"\"~까지\"(동작이 어떤 시점이나 장소까지 계속됨)"},"p":{"j":"V(＋目的語＋V)＋到＋時間/場所","e":"V (+ object + V) + 到 + time/place","k":"V(+목적어+V) + 到 + 시간/장소"},"ex":{"j":"「到」は動作が続く終点(時間や場所)を示す補語。目的語がある動詞は「V＋O＋V到…」のように動詞を繰り返す(上課上到…)。「看到」のような結果補語の到(できた、という意味)とは働きが違う。","e":"\"到\" as a complement marks the endpoint (time or place) that an action continues to. With an object, the verb repeats: V+O+V到 (上課上到...). This differs from the resultative \"到\" meaning \"successfully\" (as in 看到 = manage to see).","k":"\"到\"는 동작이 이어지는 종점(시간/장소)을 나타내는 보어이다. 목적어가 있으면 동사를 반복한다: V+O+V到...(上課上到...). \"성공적으로 ~하다\"라는 뜻의 결과보어 到(예: 看到)와는 다르다."},"eg":[{"z":"王美美今天上課<em>上到</em>下午五點。","py":"Wáng Měiměi jīntiān shàngkè shàngdào xiàwǔ wǔ diǎn.","j":"王美美は今日、午後5時まで授業を受けた。","e":"Wang Meimei had class until 5 p.m. today.","k":"왕메이메이는 오늘 오후 5시까지 수업을 들었다."},{"z":"我昨天寫作業<em>寫到</em>晚上十一點。","py":"Wǒ zuótiān xiě zuòyè xiědào wǎnshang shíyī diǎn.","j":"私は昨日、夜11時まで宿題をした。","e":"I did homework until 11 p.m. last night.","k":"나는 어제 밤 11시까지 숙제를 했다."}]},
{"id":"g2-090","cat":"副詞","t":"又1","g":{"j":"「また」(すでに起きたことの繰り返し)","e":"\"again\" (repetition of something that already happened)","k":"\"또\"(이미 일어난 일의 반복)"},"p":{"j":"又＋V(過去や既定の事実に使う)","e":"又 + V (used for a realized/past repetition)","k":"又 + V(이미 일어난 반복에 사용)"},"ex":{"j":"「又」はすでに起きた繰り返しの事実に使う(過去や現在の習慣)。まだ起きていない未来の繰り返しには「再」を使う(明天再來は○、明天又來は×)。","e":"\"又\" is used for a repetition that has already happened (a past event or a realized pattern). For a repetition expected in the future, use \"再\" instead (明天再來 is correct, ×明天又來 is not).","k":"\"又\"는 이미 일어난 반복(과거 또는 실현된 사실)에 쓴다. 아직 일어나지 않은 미래의 반복에는 \"再\"를 쓴다(明天再來는 맞고 ×明天又來는 틀리다)."},"eg":[{"z":"他<em>又</em>忘了寫功課。","py":"Tā yòu wàngle xiě gōngkè.","j":"彼はまた宿題をするのを忘れた。","e":"He forgot to do his homework again.","k":"그는 또 숙제 하는 것을 잊어버렸다."},{"z":"下雨了,公車<em>又</em>遲到了。","py":"Xiàyǔ le, gōngchē yòu chídào le.","j":"雨が降って、バスがまた遅れた。","e":"It's raining, and the bus is late again.","k":"비가 와서 버스가 또 늦었다."}]},
{"id":"g2-091","cat":"副詞","t":"又2","g":{"j":"また〜した(過去の動作の繰り返し・追加)","e":"also (did); in addition (a past, already-realized action)","k":"또(이미 일어난 동작의 반복·추가)"},"p":{"j":"V＋了……，又＋V＋了……","e":"V-le ..., yòu V-le ...","k":"V+了……, 又+V+了……"},"ex":{"j":"「又」はすでに起こった動作の繰り返しや追加を表す。未来の繰り返しを表す「再」と混同しやすいので注意(「再」は未実現、「又」は既に実現した事柄)。","e":"\"Yòu\" marks a repeated or additional action that has already happened. Don't confuse it with \"zài,\" which is used for actions not yet realized (future repetition).","k":"'又'는 이미 일어난 동작의 반복·추가를 나타낸다. 아직 일어나지 않은 미래의 반복을 나타내는 '再'와 헷갈리기 쉬우니 주의."},"eg":[{"z":"他去了臺中，<em>又</em>去了高雄。","py":"Tā qùle Táizhōng, yòu qùle Gāoxióng.","j":"彼は台中に行って、さらに高雄にも行った。","e":"He went to Taichung, and then went to Kaohsiung too.","k":"그는 타이중에 갔다가, 또 가오슝에도 갔다."},{"z":"他吃了一個漢堡，<em>又</em>吃了一份薯條。","py":"Tā chīle yí ge hànbǎo, yòu chīle yí fèn shǔtiáo.","j":"彼はハンバーガーを一つ食べて、さらにポテトを一つ食べた。","e":"He ate a hamburger, and then ate an order of fries too.","k":"그는 햄버거를 하나 먹고, 또 감자튀김도 먹었다."}]},
{"id":"g2-092","cat":"補語","t":"V過來1/過去","g":{"j":"〜してくる/〜していく(話し手を基準とする方向補語)","e":"come/go (direction of motion relative to the speaker)","k":"~해 오다/~해 가다(화자 기준 방향보어)"},"p":{"j":"V＋過來(こちらへ)／V＋過去(あちらへ)","e":"V + guòlái (toward the speaker) / V + guòqù (away from the speaker)","k":"V+過來(화자 쪽으로)/V+過去(화자에게서 멀어지는 쪽으로)"},"ex":{"j":"「過來」は話し手に近づく動き、「過去」は話し手から離れる動きを表す。方向は常に話し手の視点が基準になるので、誰の立場で話しているかを間違えないこと。","e":"\"Guòlái\" indicates movement toward the speaker's position; \"guòqù\" indicates movement away from it. Direction is always judged from the speaker's viewpoint, a common source of errors for learners.","k":"過來는 화자 쪽으로 가까워지는 이동, 過去는 화자에게서 멀어지는 이동을 나타낸다. 방향은 항상 화자의 시점이 기준이므로 혼동하지 않도록 주의."},"eg":[{"z":"小孩笑著向我跑<em>過來</em>。","py":"Xiǎohái xiàozhe xiàng wǒ pǎo guòlái.","j":"子どもは笑いながら私の方へ走ってきた。","e":"The child ran over to me, laughing.","k":"아이가 웃으면서 나에게 뛰어왔다."},{"z":"捷運來了，大家趕快跑<em>過去</em>搭車。","py":"Jiéyùn láile, dàjiā gǎnkuài pǎo guòqù dā chē.","j":"捷運が来たので、みんな急いでそちらへ走って行って乗った。","e":"The MRT arrived, so everyone hurried over to catch it.","k":"지하철이 와서 다들 서둘러 뛰어가서 탔다."}]},
{"id":"g2-093","cat":"補語","t":"V下來/下去1","g":{"j":"下りてくる/下りていく(下方向への移動を表す方向補語)","e":"come/go down (directional complement for downward movement)","k":"내려오다/내려가다(아래쪽으로의 이동을 나타내는 방향보어)"},"p":{"j":"V＋下來(下りてくる)／V＋下去(下りていく)","e":"V + xiàlái (down, toward the speaker) / V + xiàqù (down, away from the speaker)","k":"V+下來(내려오다)/V+下去(내려가다)"},"ex":{"j":"「下來・下去」は上から下への移動を表す方向補語。「下來」は話し手に近づく、または「坐下來」のように動作が落ち着く感じを含むことがあり、「下去」は話し手から離れて下る動きを表す。","e":"\"Xiàlái/xiàqù\" are directional complements for downward movement. \"Xiàlái\" often implies coming to rest or moving toward the speaker (as in \"zuò xiàlái,\" sit down), while \"xiàqù\" implies moving away and downward.","k":"下來/下去는 위에서 아래로의 이동을 나타내는 방향보어다. 下來는 화자 쪽으로 오거나 동작이 멈추는 느낌(예: 坐下來, 앉다)을, 下去는 화자에게서 멀어지며 내려가는 느낌을 준다."},"eg":[{"z":"大家到了可以找地方坐<em>下來</em>休息。","py":"Dàjiā dàole kěyǐ zhǎo dìfāng zuò xiàlái xiūxí.","j":"皆さん着いたら、どこかに座って休憩できます。","e":"Once everyone arrives, you can find a place to sit down and rest.","k":"다들 도착하면 자리를 찾아 앉아서 쉴 수 있어요."},{"z":"他慢慢地從樓梯走<em>下來</em>。","py":"Tā mànmàn de cóng lóutī zǒu xiàlái.","j":"彼はゆっくり階段を下りてきた。","e":"He slowly walked down the stairs.","k":"그는 천천히 계단을 내려왔다."}]},
{"id":"g2-094","cat":"比較","t":"A比B ......","g":{"j":"AはBより〜だ(比較)","e":"A is more ... than B","k":"A는 B보다 ~하다"},"p":{"j":"A＋比＋B＋形容詞","e":"A + bǐ + B + adjective","k":"A+比+B+형용사"},"ex":{"j":"「比」は二者を直接比較する時に使う。否定は「不比」ではなく普通「沒有」で表す(例: 弟弟沒有哥哥高)点に注意。形容詞の前に「很」は付けない。","e":"\"Bǐ\" directly compares two things. Its negation is usually expressed with \"méiyǒu\" (e.g., 弟弟沒有哥哥高) rather than \"bù bǐ,\" and \"hěn\" is not placed before the adjective in this pattern.","k":"'比'는 두 대상을 직접 비교할 때 쓴다. 부정은 보통 '不比'가 아니라 '沒有'로 표현하며(예: 弟弟沒有哥哥高), 형용사 앞에 '很'을 붙이지 않는다."},"eg":[{"z":"弟弟<em>比</em>哥哥高。","py":"Dìdi bǐ gēge gāo.","j":"弟は兄より背が高い。","e":"The younger brother is taller than the older brother.","k":"남동생은 형보다 키가 크다."},{"z":"這件衣服<em>比</em>那件貴。","py":"Zhè jiàn yīfu bǐ nà jiàn guì.","j":"この服はあの服より高い(値段が)。","e":"This piece of clothing is more expensive than that one.","k":"이 옷은 저 옷보다 비싸다."}]},
{"id":"g2-095","cat":"比較","t":"A跟B一樣......","g":{"j":"AとBは(〜の点で)同じだ(同等比較)","e":"A is the same as / as ... as B","k":"A는 B와 같다/만큼 ~하다"},"p":{"j":"A＋跟＋B＋一樣(＋形容詞)","e":"A + gēn + B + yíyàng (+ adjective)","k":"A+跟+B+一樣(+형용사)"},"ex":{"j":"「跟……一樣」は二者が同程度・同じであることを表す。「一樣」の後に形容詞を続けると、具体的にどの点で同じかを示せる(省略すると「全く同じ」の意味になる)。優劣を表す「比」構文とは違う点に注意。","e":"\"Gēn ... yíyàng\" expresses equality between two things. Adding an adjective after \"yíyàng\" specifies in what way they're equal (omitting it implies they are identical overall). Unlike the \"bǐ\" comparative, it shows sameness, not superiority.","k":"'跟……一樣'는 두 대상이 동등함을 나타내는 표현이다. '一樣' 뒤에 형용사를 붙이면 구체적으로 어떤 점에서 같은지 나타내고, 생략하면 '완전히 같다'는 뜻이 된다. 우열을 나타내는 '比' 구문과는 다르다는 점에 주의."},"eg":[{"z":"這本書<em>跟</em>那本書<em>一樣</em>貴。","py":"Zhè běn shū gēn nà běn shū yíyàng guì.","j":"この本はあの本と同じくらい(値段が)高い。","e":"This book is as expensive as that one.","k":"이 책은 저 책만큼 비싸다."},{"z":"我的身高<em>跟</em>姊姊<em>一樣</em>。","py":"Wǒ de shēngāo gēn jiějie yíyàng.","j":"私の身長は姉と同じだ。","e":"My height is the same as my older sister's.","k":"내 키는 언니와 같다."}]},
{"id":"g2-096","cat":"接続","t":"一......就......","g":{"j":"〜するとすぐに〜する","e":"as soon as...then...","k":"~하자마자 ~하다"},"p":{"j":"一＋動作A＋就＋動作B","e":"Yī + Action A + jiù + Action B","k":"一 + 동작A + 就 + 동작B"},"ex":{"j":"「一」の直後の音節が第4声なら「一」はyíと読む(下課xiàkèの下は4声)。2つの動作が間を置かずすぐに続くことを表す。","e":"Marks two actions happening in immediate succession with almost no gap; note 一 is read \"yí\" before a 4th-tone syllable (as in xiàkè, since 下 is tone 4).","k":"두 동작이 거의 사이 없이 곧바로 이어짐을 나타낸다. 一 뒤 음절이 4성이면 yí로 읽는다(下xià가 4성이라 xiàkè 앞에서 yí)."},"eg":[{"z":"他們<em>一下課就</em>回家。","py":"Tāmen yí xiàkè jiù huíjiā.","j":"彼らは授業が終わるとすぐに家に帰る。","e":"They go home as soon as class ends.","k":"그들은 수업이 끝나자마자 집에 간다."},{"z":"我<em>一到家就</em>洗手。","py":"Wǒ yí dào jiā jiù xǐshǒu.","j":"私は家に着くとすぐに手を洗う。","e":"I wash my hands as soon as I get home.","k":"나는 집에 도착하자마자 손을 씻는다."}]},
{"id":"g2-097","cat":"特殊構文","t":"（是）......的","g":{"j":"すでに起きたことの時間・場所・方法を強調する","e":"emphasizes when/where/how a past event happened","k":"이미 일어난 일의 시간·장소·방법을 강조"},"p":{"j":"(是)＋強調したい部分＋動詞＋的","e":"(Shì) + emphasized element + Verb + de","k":"(是) + 강조할 부분 + 동사 + 的"},"ex":{"j":"聞き手も知っている過去の出来事の時間・場所・手段などの詳細を強調する。単純に出来事の発生を報告する「了」とは違い、こちらは背景情報にスポットを当てる。","e":"Highlights details (time/place/means) of an event both speakers already know happened; unlike 了, which simply reports that an event occurred, 是...的 spotlights the circumstances.","k":"상대도 이미 알고 있는 과거 사건의 시간·장소·수단 등을 강조한다. 사건 발생 자체를 보고하는 了와 달리 배경 정보에 초점을 둔다."},"eg":[{"z":"我<em>是從美國來的</em>。","py":"Wǒ shì cóng Měiguó lái de.","j":"私はアメリカから来たのです。","e":"I came from the United States.","k":"저는 미국에서 온 것입니다."},{"z":"他<em>是坐飛機來的</em>。","py":"Tā shì zuò fēijī lái de.","j":"彼は飛行機で来たのです。","e":"He came by plane.","k":"그는 비행기를 타고 온 것입니다."}]},
{"id":"g2-098","cat":"特殊構文","t":"好/難+V","g":{"j":"〜しやすい／〜しにくい","e":"easy to.../hard to...","k":"~하기 쉽다/어렵다"},"p":{"j":"好／難＋動詞","e":"Hǎo/Nán + Verb","k":"好/難 + 동사"},"ex":{"j":"「好/難」の後に動詞を置き、その動作をする側から見た難易度を表す(好吃=食べやすい→美味しい)。主語は動詞の意味上の目的語であって、動作をする人ではない点に注意。","e":"好/難 before a verb expresses how easy or hard it is to perform that action (好吃 = easy to eat = delicious); the subject is the semantic object of the verb, not the one performing it.","k":"好/難 뒤에 동사를 두어 그 동작을 하기가 쉬운지 어려운지를 나타낸다(好吃=먹기 쉽다→맛있다). 주어는 동작을 하는 사람이 아니라 동사의 의미상 목적어임에 유의."},"eg":[{"z":"這個字很<em>難寫</em>。","py":"Zhège zì hěn nán xiě.","j":"この字は書きにくい。","e":"This character is hard to write.","k":"이 글자는 쓰기 어렵다."},{"z":"這台電腦很<em>好用</em>。","py":"Zhè tái diànnǎo hěn hǎoyòng.","j":"このパソコンはとても使いやすい。","e":"This computer is very easy to use.","k":"이 컴퓨터는 아주 사용하기 편하다."}]},
{"id":"g2-099","cat":"接続","t":"了......就......","g":{"j":"〜したら、すぐに〜する","e":"after doing...then...","k":"~하고 나서 바로 ~하다"},"p":{"j":"動詞A＋了＋(目的語)＋就＋動詞B","e":"Verb A + le + (Object) + jiù + Verb B","k":"동사A + 了 + (목적어) + 就 + 동사B"},"ex":{"j":"[[g2-096]]の「一......就......」と似るが、こちらは「了」で動作Aが完了してから動作Bが続くことを示し、間に時間差があってもよい。「一...就」はほぼ同時・即座であることを強調する点が違う。","e":"Similar to 一...就... ([[g2-096]]), but here 了 marks that Action A is completed before Action B follows, so a time gap is allowed; 一...就... instead stresses near-simultaneity.","k":"[[g2-096]]의 一......就......와 비슷하지만, 了로 동작A가 끝난 뒤 동작B가 이어짐을 나타내며 시간차가 있어도 된다. 一...就...는 거의 동시임을 강조한다는 점이 다르다."},"eg":[{"z":"我<em>吃了早飯就</em>去上課。","py":"Wǒ chīle zǎofàn jiù qù shàngkè.","j":"私は朝ご飯を食べたらすぐに授業に行く。","e":"I go to class right after I eat breakfast.","k":"나는 아침을 먹고 나서 바로 수업에 간다."},{"z":"他<em>做了功課就</em>出去玩。","py":"Tā zuòle gōngkè jiù chūqù wán.","j":"彼は宿題をやったらすぐに遊びに出かける。","e":"He goes out to play right after he finishes his homework.","k":"그는 숙제를 하고 나서 바로 놀러 나간다."}]},
{"id":"g2-100","cat":"介詞","t":"從......往......","g":{"j":"〜から〜(の方向)へ","e":"from...towards...","k":"~에서 ~쪽으로"},"p":{"j":"從＋起点＋往＋方向／地点＋動詞","e":"Cóng + starting point + wǎng + direction/place + Verb","k":"從 + 출발점 + 往 + 방향/장소 + 동사"},"ex":{"j":"「從」で出発点を、「往」で進む方向・行き先を示し、道案内でよく使う。「往」の後には方向詞(左/右/前など)や地名が続く。","e":"從 marks the starting point and 往 marks the direction or destination of movement; very common when giving directions, with 往 followed by a direction word (left/right) or a place name.","k":"從은 출발점을, 往은 이동 방향이나 목적지를 나타내며 길 안내에서 자주 쓰인다. 往 뒤에는 방향어(왼쪽/오른쪽 등)나 지명이 온다."},"eg":[{"z":"<em>從學校往圖書館走</em>就到了。","py":"Cóng xuéxiào wǎng túshūguǎn zǒu jiù dào le.","j":"学校から図書館の方に向かって歩けば着く。","e":"Walk from the school towards the library and you'll get there.","k":"학교에서 도서관 쪽으로 걸어가면 도착한다."},{"z":"<em>從這裡往右轉</em>就是捷運站。","py":"Cóng zhèlǐ wǎng yòu zhuǎn jiù shì jiéyùnzhàn.","j":"ここから右に曲がるとMRTの駅です。","e":"Turn right from here and it's the MRT station.","k":"여기서 오른쪽으로 돌면 MRT역이다."}]},
{"id":"g2-101","cat":"介詞","t":"A離B......","g":{"j":"AとBの間の距離・時間を表す","e":"expresses the distance or time between A and B","k":"A와 B 사이의 거리·시간을 나타냄"},"p":{"j":"A ＋ 離 ＋ B ＋ (距離/時間)","e":"A + lí + B + (distance/time)","k":"A + 離 + B + (거리/시간)"},"ex":{"j":"離は2点間の隔たり(距離・時間)を表す前置詞で、方向を表す從・到とは違う。離のあとには目的地が来て動詞は続かず、そのまま距離や時間の表現が続く点に注意。","e":"Lí marks the distance or time gap between two points; unlike cóng (\"from,\" motion) or dào (\"to,\" destination), lí never takes a verb directly after it — it's followed straight by a distance or time expression.","k":"離는 두 지점 사이의 거리·시간 차이를 나타내는 전치사로, 이동을 뜻하는 從·到와 다르다. 離 뒤에는 동사 없이 바로 거리·시간 표현이 온다."},"eg":[{"z":"我家<em>離學校</em>走路只要十分鐘。","py":"Wǒ jiā lí xuéxiào zǒulù zhǐyào shí fēnzhōng.","j":"うちから学校までは歩いてたった10分です。","e":"It only takes ten minutes to walk from my house to school.","k":"우리 집에서 학교까지 걸어서 10분밖에 안 걸려요."},{"z":"郵局<em>離我家</em>不遠，騎腳踏車五分鐘就到。","py":"Yóujú lí wǒ jiā bù yuǎn, qí jiǎotàchē wǔ fēnzhōng jiù dào.","j":"郵便局はうちから遠くなくて、自転車で5分で着きます。","e":"The post office isn't far from my house — it's five minutes by bike.","k":"우체국은 우리 집에서 멀지 않아요. 자전거로 5분이면 도착해요."}]},
{"id":"g2-102","cat":"特殊構文","t":"VP 的 N","g":{"j":"動詞句(VP)で名詞を修飾する:VP＋的＋N","e":"a verb phrase modifies a noun with 的","k":"동사구(VP)가 的로 명사를 수식함"},"p":{"j":"VP ＋ 的 ＋ N","e":"VP + de + N","k":"VP + 的 + N"},"ex":{"j":"動詞句をそのまま名詞の前に置き、的でつないで修飾語にする。日本語の関係節と違い関係代名詞がなく、Nが意味上VPの主語か目的語かは文脈で判断する必要がある。","e":"A verb phrase placed before 的 works like a relative clause modifying the noun that follows; there's no relative pronoun as in English, so you must infer from context whether N is the logical subject or object of the VP.","k":"동사구를 명사 앞에 놓고 的로 연결하면 관계절처럼 명사를 수식한다. 영어의 관계대명사가 없으므로 N이 VP의 주어인지 목적어인지는 문맥으로 판단해야 한다."},"eg":[{"z":"我認識一位<em>會說德文的英文老師</em>。","py":"Wǒ rènshì yí wèi huì shuō Déwén de Yīngwén lǎoshī.","j":"私はドイツ語が話せる英語の先生を一人知っている。","e":"I know an English teacher who can speak German.","k":"저는 독일어를 할 줄 아는 영어 선생님을 한 분 알아요."},{"z":"我有一個<em>很會做菜的室友</em>。","py":"Wǒ yǒu yí ge hěn huì zuò cài de shìyǒu.","j":"私にはとても料理が上手なルームメイトがいる。","e":"I have a roommate who's really good at cooking.","k":"저는 요리를 아주 잘하는 룸메이트가 있어요."}]},
{"id":"g2-103","cat":"疑問","t":"多+Vs？","g":{"j":"多＋形容詞で程度・数値をたずねる","e":"duō + adjective asks about a degree or measurement","k":"多+형용사로 정도(수치)를 물음"},"p":{"j":"多 ＋ Vs(高/大/遠...)？","e":"duō + stative verb (gāo/dà/yuǎn...)?","k":"多 + Vs(高/大/遠 등)?"},"ex":{"j":"多は「どれくらい」の意味で、高・大・遠など尺度を持つ性質形容詞(Vs)の前に置いて数値や程度を尋ねる。個数を問う幾＋量詞と違い、多は量詞なしでVsに直接つく。","e":"Duō means \"how\" and attaches directly to scalar stative verbs like gāo/dà/yuǎn to ask for a measurement or degree; unlike jǐ + measure word (which asks for a small countable number), duō needs no measure word and just goes straight before the adjective.","k":"多는 '얼마나'라는 뜻으로 高·大·遠처럼 정도를 가진 형용사(Vs) 앞에 붙어 수치나 정도를 묻는다. 개수를 묻는 幾+양사와 달리 多는 양사 없이 형용사에 바로 붙는다."},"eg":[{"z":"你哥哥<em>多高</em>？","py":"Nǐ gēge duō gāo?","j":"あなたのお兄さんはどのくらい背が高いですか。","e":"How tall is your older brother?","k":"형(오빠)은 키가 얼마나 커요?"},{"z":"妹妹今年<em>多大</em>？","py":"Mèimei jīnnián duō dà?","j":"妹さんは今年何歳ですか。","e":"How old is your younger sister this year?","k":"여동생은 올해 몇 살이에요?"}]},
{"id":"g2-104","cat":"補語","t":"V進/出/上/回+（......）來/去","g":{"j":"V＋進/出/上/回＋(目的語)＋來/去で移動方向を表す","e":"V + in/out/up/back + (object) + come/go shows the direction of movement","k":"V+進/出/上/回+(목적어)+來/去로 이동 방향을 나타냄"},"p":{"j":"V ＋ 進/出/上/回 ＋ (目的語) ＋ 來/去","e":"V + jìn/chū/shàng/huí + (object) + lái/qù","k":"V + 進/出/上/回 + (목적어) + 來/去"},"ex":{"j":"進/出/上/回は動作の経路(内へ/外へ/上へ/戻る)を、來/去は話し手に近づくか離れるかを示す複合方向補語。場所以外の目的語が入るときは來/去の前に置く点が単純方向補語との違い。","e":"Jìn/chū/shàng/huí show the path of motion (in/out/up/back), while lái/qù show whether it's toward or away from the speaker; when a non-place object is added, it goes between the two parts (V + direction + object + lái/qù), which is the key difference from a simple two-part directional complement.","k":"進/出/上/回는 이동 경로(안/밖/위/되돌아옴)를, 來/去는 화자 쪽으로 오는지 멀어지는지를 나타내는 복합방향보어이다. 장소가 아닌 목적어가 있을 때는 來/去 앞에 넣는 점이 단순방향보어와 다르다."},"eg":[{"z":"電梯等太久了，我從二樓<em>走上來</em>。","py":"Diàntī děng tài jiǔ le, wǒ cóng èr lóu zǒu shànglai.","j":"エレベーターを待つのが長すぎたので、私は2階から歩いて上がってきた。","e":"The elevator was taking too long, so I walked up from the second floor.","k":"엘리베이터를 너무 오래 기다려서 저는 2층에서 걸어 올라왔어요."},{"z":"他<em>跑回宿舍去</em>了。","py":"Tā pǎo huí sùshè qù le.","j":"彼は寮に走って帰って行った。","e":"He ran back to the dorm.","k":"그는 기숙사로 뛰어갔어요."}]},
{"id":"g2-105","cat":"特殊構文","t":"零代詞","g":{"j":"同じ主語が続くとき代名詞を省略する","e":"the pronoun is dropped when the same subject continues into the next clause","k":"같은 주어가 이어질 때 대명사를 생략함"},"p":{"j":"S＋V1...後，(Ø)＋V2...","e":"S + V1..., (Ø) + V2...","k":"S+V1...後，(Ø)+V2..."},"ex":{"j":"前の文脈から主語が明らかなとき、後続節で代名詞(他/她/它など)を繰り返さず省略するのが自然。日本語の主語省略と似ているが、英語のように毎回heやsheを入れると不自然になる。","e":"When the subject is already clear from context, Mandarin naturally drops the pronoun (tā, etc.) in the following clause instead of repeating it — similar to Japanese subject omission, but unlike English, which requires restating \"he/she\" in every clause.","k":"앞 문맥에서 주어가 명확할 때 뒤 절에서 대명사(他/她/它 등)를 반복하지 않고 생략하는 것이 자연스럽다. 영어처럼 매번 he/she를 넣으면 오히려 어색하다."},"eg":[{"z":"他看了菜單後，<em>決定點一份三明治</em>。","py":"Tā kàn le càidān hòu, juédìng diǎn yí fèn sānmíngzhì.","j":"彼はメニューを見た後、サンドイッチを一つ注文することにした。","e":"After looking at the menu, he decided to order a sandwich.","k":"그는 메뉴를 본 후에 샌드위치 하나를 주문하기로 했다."},{"z":"她下課以後，<em>就去圖書館看書了</em>。","py":"Tā xiàkè yǐhòu, jiù qù túshūguǎn kàn shū le.","j":"彼女は授業が終わった後、図書館へ行って本を読んだ。","e":"After class, she went to the library to read.","k":"그녀는 수업이 끝난 후에 도서관에 가서 책을 읽었다."}]},
{"id":"g2-106","cat":"数量","t":"概數","g":{"j":"大まかな数を表す","e":"Expressing an approximate number","k":"대략적인 수를 나타냄"},"p":{"j":"十位数＋幾（＋量詞）","e":"Round ten + 幾 (+ classifier)","k":"십 단위 + 幾 (+ 양사)"},"ex":{"j":"「幾」は十の位の後ろについて「〜幾つ」という大まかな数を表す(十幾個・二十幾歲など)。疑問文の「幾個?」は数を尋ねる用法で、答えの「十幾個」が概數の典型例。","e":"'幾' attached after a round ten (十幾, 二十幾) expresses an approximate number like '-some'. A question such as 幾個? simply asks 'how many', while an answer like 十幾個 is the typical approximate-number form.","k":"'幾'는 '十幾, 二十幾'처럼 십 단위 뒤에 붙어 '~여 개' 같은 대략적인 수를 나타낸다. 질문 '幾個?'는 단순히 개수를 묻는 것이고, 대답 '十幾個'가 전형적인 개수(概數) 표현이다."},"eg":[{"z":"你吃了<em>幾</em>個餃子？","py":"Nǐ chīle jǐ ge jiǎozi?","j":"餃子を何個食べましたか？","e":"How many dumplings did you eat?","k":"만두를 몇 개 먹었어요?"},{"z":"他大概<em>二十幾</em>歲。","py":"Tā dàgài èrshí jǐ suì.","j":"彼はだいたい二十代です。","e":"He's in his twenties, roughly.","k":"그는 대략 이십 대예요."}]},
{"id":"g2-107","cat":"特殊構文","t":"話題優先","g":{"j":"話題を文頭に出す","e":"Placing the topic at the front of the sentence","k":"화제를 문장 맨 앞에 놓음"},"p":{"j":"話題語，コメント","e":"Topic, + Comment","k":"화제어, 설명"},"ex":{"j":"中国語(特に台湾の話しことば)では、文の主語でなくても「話題」となる名詞を文頭に置き、コンマで区切って後ろで説明する。「筆」は「幾塊錢一枝」の文法上の主語ではないが、話題として先に出せる。","e":"In spoken Mandarin (especially Taiwan Mandarin), a noun that is not the grammatical subject can still be fronted as the 'topic', set off by a pause/comma, with the rest of the sentence commenting on it — 筆 isn't the subject of 幾塊錢一枝 but can still lead the sentence as its topic.","k":"(특히 대만) 구어체 중국어에서는 문법상 주어가 아니어도 '화제'가 되는 명사를 문장 맨 앞에 놓고 쉼표로 끊은 뒤 나머지 부분에서 설명한다. '筆'는 '幾塊錢一枝'의 문법적 주어가 아니지만 화제로 앞에 나올 수 있다."},"eg":[{"z":"<em>筆</em>，幾塊錢一枝呢？","py":"Bǐ, jǐ kuài qián yì zhī ne?","j":"ペンは、一本いくらですか？","e":"As for pens, how much is one?","k":"펜은 한 자루에 얼마예요?"},{"z":"<em>西瓜</em>，一顆多少錢？","py":"Xīguā, yì kē duōshǎo qián?","j":"スイカは、一個いくらですか？","e":"As for watermelons, how much is one?","k":"수박은 한 통에 얼마예요?"}]},
{"id":"l2-16","cat":"句型","t":"每…都…","g":{"j":"毎〜必ず…","e":"every ~ (always) …","k":"매 ~마다 반드시 …"},"p":{"j":"每 ＋ 時間/名詞 ＋ 都 ＋ V","e":"每 + time/noun + 都 + V","k":"每 + 시간/명사 + 都 + V"},"ex":{"j":"「每」を使うときは後ろにほぼ必ず「都」を付けるのがポイント。「每天都運動（毎日運動する）」。「都」を忘れると不自然になる。","e":"每 (every) is almost always paired with 都: 每天都運動. Dropping 都 sounds unnatural.","k":"\"每\"를 쓸 때는 뒤에 거의 반드시 \"都\"를 붙인다: 每天都運動."},"eg":[{"z":"我<em>每</em>個週末<em>都</em>去爬山。","py":"Wǒ měi ge zhōumò dōu qù páshān.","j":"私は毎週末、必ず山登りに行きます。","e":"I go hiking every single weekend.","k":"저는 주말마다 등산을 가요."},{"z":"<em>每</em>家手搖店<em>都</em>有自己的招牌。","py":"Měi jiā shǒuyáodiàn dōu yǒu zìjǐ de zhāopái.","j":"どのドリンクスタンドにもそれぞれの看板メニューがあります。","e":"Every drink shop has its own signature item.","k":"모든 음료 가게에는 각자의 대표 메뉴가 있어요."}]}
];
if (typeof window !== "undefined") window.GRAMMAR_L2 = GRAMMAR_L2;
